window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["OBA"]={"book":"OBA","editions":{"hbo-source":[[1,1,"חֲז֖וֹן עֹֽבַדְיָ֑ה כֹּֽה־אָמַר֩ אֲדֹנָ֨⁠י יְהוִ֜ה לֶ⁠אֱד֗וֹם שְׁמוּעָ֨ה שָׁמַ֜עְנוּ מֵ⁠אֵ֤ת יְהוָה֙ וְ⁠צִיר֙ בַּ⁠גּוֹיִ֣ם שֻׁלָּ֔ח ק֛וּמוּ וְ⁠נָק֥וּמָה עָלֶי⁠הָ לַ⁠מִּלְחָמָֽה׃","ẖàz֖wòn ʻòֽbadĕyá֑h kòֽ̇h-ʼámar֩ ʼàdòná֨⁠y yĕhwi֜h le⁠ʼèd֗wòm şĕ̌mẇʻá֨h şá̌ma֜ʻĕnẇ mé⁠ʼé֤ţ yĕhwáh֙ wĕ⁠ẕiyr֙ bȧ⁠ġwòyi֣m şǔlá̇֔ẖ q֛ẇmẇ wĕ⁠náq֥ẇmáh ʻáley⁠há la⁠mi̇lĕẖámáֽh׃"],[1,2,"הִנֵּ֥ה קָטֹ֛ן נְתַתִּ֖י⁠ךָ בַּ⁠גּוֹיִ֑ם בָּז֥וּי אַתָּ֖ה מְאֹֽד׃","hiné֥̇h qátò֛n nĕţaţi֖̇y⁠ká bȧ⁠ġwòyi֑m bá̇z֥ẇy ʼaţá֖̇h mĕʼòֽd׃"],[1,3,"זְד֤וֹן לִבְּ⁠ךָ֙ הִשִּׁיאֶ֔⁠ךָ שֹׁכְנִ֥י בְ⁠חַגְוֵי־סֶּ֖לַע מְר֣וֹם שִׁבְתּ֑⁠וֹ אֹמֵ֣ר בְּ⁠לִבּ֔⁠וֹ מִ֥י יוֹרִדֵ֖⁠נִי אָֽרֶץ׃","zĕd֤wòn libĕ̇⁠ká֙ hişi̇̌yʼe֔⁠ká şò̌kĕni֥y bĕ⁠ẖagĕwéy-sė֖laʻ mĕr֣wòm şǐbĕţ֑̇⁠wò ʼòmé֣r bĕ̇⁠liḃ֔⁠wò mi֥y ywòridé֖⁠niy ʼáֽreẕ׃"],[1,4,"אִם־תַּגְבִּ֣יהַּ כַּ⁠נֶּ֔שֶׁר וְ⁠אִם־בֵּ֥ין כּֽוֹכָבִ֖ים שִׂ֣ים קִנֶּ֑⁠ךָ מִ⁠שָּׁ֥ם אוֹרִֽידְ⁠ךָ֖ נְאֻם־יְהוָֽה׃","ʼim-ţȧgĕbi֣̇yhȧ kȧ⁠nė֔şěr wĕ⁠ʼim-bé֥̇yn kֽ̇wòkábi֖ym şî֣ym qinė֑⁠ká mi⁠şá֥̇̌m ʼwòriֽydĕ⁠ká֖ nĕʼum-yĕhwáֽh׃"],[1,5,"אִם־גַּנָּבִ֤ים בָּאֽוּ־לְ⁠ךָ֙ אִם־שׁ֣וֹדְדֵי לַ֔יְלָה אֵ֣יךְ נִדְמֵ֔יתָה הֲ⁠ל֥וֹא יִגְנְב֖וּ דַּיָּ֑⁠ם אִם־בֹּֽצְרִים֙ בָּ֣אוּ לָ֔⁠ךְ הֲ⁠ל֖וֹא יַשְׁאִ֥ירוּ עֹלֵלֽוֹת׃","ʼim-gȧná̇bi֤ym bá̇ʼֽẇ-lĕ⁠ká֙ ʼim-ş֣̌wòdĕdéy la֔yĕláh ʼé֣ykĕ nidĕmé֔yţáh hà⁠l֥wòʼ yigĕnĕb֖ẇ dȧyá֑̇⁠m ʼim-bòֽ̇ẕĕriym֙ bá֣̇ʼẇ lá֔⁠kĕ hà⁠l֖wòʼ yaşĕ̌ʼi֥yrẇ ʻòlélֽwòţ׃"],[1,6,"אֵ֚יךְ נֶחְפְּשׂ֣וּ עֵשָׂ֔ו נִבְע֖וּ מַצְפֻּנָֽי⁠ו׃","ʼé֚ykĕ neẖĕpĕ̇ş֣̂ẇ ʻéşá̂֔w nibĕʻ֖ẇ maẕĕpu̇náֽy⁠w׃"],[1,7,"עַֽד־הַ⁠גְּב֣וּל שִׁלְּח֗וּ⁠ךָ כֹּ֚ל אַנְשֵׁ֣י בְרִיתֶ֔⁠ךָ הִשִּׁיא֛וּ⁠ךָ יָכְל֥וּ לְ⁠ךָ֖ אַנְשֵׁ֣י שְׁלֹמֶ֑⁠ךָ לַחְמְ⁠ךָ֗ יָשִׂ֤ימוּ מָזוֹר֙ תַּחְתֶּ֔י⁠ךָ אֵ֥ין תְּבוּנָ֖ה בּֽ⁠וֹ׃","ʻaֽd-ha⁠gĕ̇b֣ẇl şǐlĕ̇ẖ֗ẇ⁠ká kò֚̇l ʼanĕşé֣̌y bĕriyţe֔⁠ká hişi̇̌yʼ֛ẇ⁠ká yákĕl֥ẇ lĕ⁠ká֖ ʼanĕşé֣̌y şĕ̌lòme֑⁠ká laẖĕmĕ⁠ká֗ yáşî֤ymẇ mázwòr֙ ţȧẖĕţė֔y⁠ká ʼé֥yn ţĕ̇bẇná֖h ḃֽ⁠wò׃"],[1,8,"הֲ⁠ל֛וֹא בַּ⁠יּ֥וֹם הַ⁠ה֖וּא נְאֻם־יְהוָ֑ה וְ⁠הַאֲבַדְתִּ֤י חֲכָמִים֙ מֵֽ⁠אֱד֔וֹם וּ⁠תְבוּנָ֖ה מֵ⁠הַ֥ר עֵשָֽׂו׃","hà⁠l֛wòʼ bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ nĕʼum-yĕhwá֑h wĕ⁠haʼàbadĕţi֤̇y ẖàkámiym֙ méֽ⁠ʼèd֔wòm ẇ⁠ţĕbẇná֖h mé⁠ha֥r ʻéşáֽ̂w׃"],[1,9,"וְ⁠חַתּ֥וּ גִבּוֹרֶ֖י⁠ךָ תֵּימָ֑ן לְמַ֧עַן יִכָּֽרֶת־אִ֛ישׁ מֵ⁠הַ֥ר עֵשָׂ֖ו מִ⁠קָּֽטֶל׃","wĕ⁠ẖaţ֥̇ẇ giḃwòre֖y⁠ká ţé̇ymá֑n lĕma֧ʻan yikáֽ̇reţ-ʼi֛yş̌ mé⁠ha֥r ʻéşá֖̂w mi⁠qáֽ̇tel׃"],[1,10,"מֵ⁠חֲמַ֛ס אָחִ֥י⁠ךָ יַעֲקֹ֖ב תְּכַסְּ⁠ךָ֣ בוּשָׁ֑ה וְ⁠נִכְרַ֖תָּ לְ⁠עוֹלָֽם׃","mé⁠ẖàma֛s ʼáẖi֥y⁠ká yaʻàqò֖b ţĕ̇kasĕ̇⁠ká֣ bẇşá֑̌h wĕ⁠nikĕra֖ţá̇ lĕ⁠ʻwòláֽm׃"],[1,11,"בְּ⁠יוֹם֙ עֲמָֽדְ⁠ךָ֣ מִ⁠נֶּ֔גֶד בְּ⁠י֛וֹם שְׁב֥וֹת זָרִ֖ים חֵיל֑⁠וֹ וְ⁠נָכְרִ֞ים בָּ֣אוּ שער⁠ו וְ⁠עַל־יְרוּשָׁלִַ֨ם֙ יַדּ֣וּ גוֹרָ֔ל גַּם־אַתָּ֖ה כְּ⁠אַחַ֥ד מֵ⁠הֶֽם׃","bĕ̇⁠ywòm֙ ʻàmáֽdĕ⁠ká֣ mi⁠nė֔ged bĕ̇⁠y֛wòm şĕ̌b֥wòţ zári֖ym ẖéyl֑⁠wò wĕ⁠nákĕri֞ym bá֣̇ʼẇ şʻr⁠w wĕ⁠ʻal-yĕrẇşá̌lia֨m֙ yaḋ֣ẇ gwòrá֔l gȧm-ʼaţá֖̇h kĕ̇⁠ʼaẖa֥d mé⁠heֽm׃"],[1,12,"וְ⁠אַל־תֵּ֤רֶא בְ⁠יוֹם־אָחִ֨י⁠ךָ֙ בְּ⁠י֣וֹם נָכְר֔⁠וֹ וְ⁠אַל־תִּשְׂמַ֥ח לִ⁠בְנֵֽי־יְהוּדָ֖ה בְּ⁠י֣וֹם אָבְדָ֑⁠ם וְ⁠אַל־תַּגְדֵּ֥ל פִּ֖י⁠ךָ בְּ⁠י֥וֹם צָרָֽה׃","wĕ⁠ʼal-ţé֤̇reʼ bĕ⁠ywòm-ʼáẖi֨y⁠ká֙ bĕ̇⁠y֣wòm nákĕr֔⁠wò wĕ⁠ʼal-ţi̇şĕ̂ma֥ẖ li⁠bĕnéֽy-yĕhẇdá֖h bĕ̇⁠y֣wòm ʼábĕdá֑⁠m wĕ⁠ʼal-ţȧgĕdé֥̇l pi֖̇y⁠ká bĕ̇⁠y֥wòm ẕáráֽh׃"],[1,13,"אַל־תָּב֤וֹא בְ⁠שַֽׁעַר־עַמִּ⁠י֙ בְּ⁠י֣וֹם אֵידָ֔⁠ם אַל־תֵּ֧רֶא גַם־אַתָּ֛ה בְּ⁠רָעָת֖⁠וֹ בְּ⁠י֣וֹם אֵיד֑⁠וֹ וְ⁠אַל־תִּשְׁלַ֥חְנָה בְ⁠חֵיל֖⁠וֹ בְּ⁠י֥וֹם אֵידֽ⁠וֹ׃","ʼal-ţá̇b֤wòʼ bĕ⁠şǎֽʻar-ʻami̇⁠y֙ bĕ̇⁠y֣wòm ʼéydá֔⁠m ʼal-ţé֧̇reʼ gam-ʼaţá֛̇h bĕ̇⁠ráʻáţ֖⁠wò bĕ̇⁠y֣wòm ʼéyd֑⁠wò wĕ⁠ʼal-ţi̇şĕ̌la֥ẖĕnáh bĕ⁠ẖéyl֖⁠wò bĕ̇⁠y֥wòm ʼéydֽ⁠wò׃"],[1,14,"וְ⁠אַֽל־תַּעֲמֹד֙ עַל־הַ⁠פֶּ֔רֶק לְ⁠הַכְרִ֖ית אֶת־פְּלִיטָ֑י⁠ו וְ⁠אַל־תַּסְגֵּ֥ר שְׂרִידָ֖י⁠ו בְּ⁠י֥וֹם צָרָֽה׃","wĕ⁠ʼaֽl-ţȧʻàmòd֙ ʻal-ha⁠pė֔req lĕ⁠hakĕri֖yţ ʼeţ-pĕ̇liytá֑y⁠w wĕ⁠ʼal-ţȧsĕgé֥̇r şĕ̂riydá֖y⁠w bĕ̇⁠y֥wòm ẕáráֽh׃"],[1,15,"כִּֽי־קָר֥וֹב יוֹם־יְהוָ֖ה עַל־כָּל־הַ⁠גּוֹיִ֑ם כַּ⁠אֲשֶׁ֤ר עָשִׂ֨יתָ֙ יֵעָ֣שֶׂה לָּ֔⁠ךְ גְּמֻלְ⁠ךָ֖ יָשׁ֥וּב בְּ⁠רֹאשֶֽׁ⁠ךָ׃","kiֽ̇y-qár֥wòb ywòm-yĕhwá֖h ʻal-ká̇l-ha⁠ġwòyi֑m kȧ⁠ʼàşě֤r ʻáşî֨yţá֙ yéʻá֣şêh lá̇֔⁠kĕ gĕ̇mulĕ⁠ká֖ yáş֥̌ẇb bĕ̇⁠ròʼşěֽ⁠ká׃"],[1,16,"כִּ֗י כַּֽ⁠אֲשֶׁ֤ר שְׁתִיתֶם֙ עַל־הַ֣ר קָדְשִׁ֔⁠י יִשְׁתּ֥וּ כָֽל־הַ⁠גּוֹיִ֖ם תָּמִ֑יד וְ⁠שָׁת֣וּ וְ⁠לָע֔וּ וְ⁠הָי֖וּ כְּ⁠ל֥וֹא הָיֽוּ׃","ki̇֗y kȧֽ⁠ʼàşě֤r şĕ̌ţiyţem֙ ʻal-ha֣r qádĕşǐ֔⁠y yişĕ̌ţ֥̇ẇ káֽl-ha⁠ġwòyi֖m ţá̇mi֑yd wĕ⁠şá̌ţ֣ẇ wĕ⁠láʻ֔ẇ wĕ⁠háy֖ẇ kĕ̇⁠l֥wòʼ háyֽẇ׃"],[1,17,"וּ⁠בְ⁠הַ֥ר צִיּ֛וֹן תִּהְיֶ֥ה פְלֵיטָ֖ה וְ⁠הָ֣יָה קֹ֑דֶשׁ וְ⁠יָֽרְשׁוּ֙ בֵּ֣ית יַֽעֲקֹ֔ב אֵ֖ת מוֹרָֽשֵׁי⁠הֶם׃","ẇ⁠bĕ⁠ha֥r ẕiẏ֛wòn ţi̇hĕye֥h pĕléytá֖h wĕ⁠há֣yáh qò֑deş̌ wĕ⁠yáֽrĕş̌ẇ֙ bé֣̇yţ yaֽʻàqò֔b ʼé֖ţ mwòráֽşé̌y⁠hem׃"],[1,18,"וְ⁠הָיָה֩ בֵית־יַעֲקֹ֨ב אֵ֜שׁ וּ⁠בֵ֧ית יוֹסֵ֣ף לֶהָבָ֗ה וּ⁠בֵ֤ית עֵשָׂו֙ לְ⁠קַ֔שׁ וְ⁠דָלְק֥וּ בָ⁠הֶ֖ם וַ⁠אֲכָל֑וּ⁠ם וְ⁠לֹֽא־יִֽהְיֶ֤ה שָׂרִיד֙ לְ⁠בֵ֣ית עֵשָׂ֔ו כִּ֥י יְהוָ֖ה דִּבֵּֽר׃","wĕ⁠háyáh֩ béyţ-yaʻàqò֨b ʼé֜ş̌ ẇ⁠bé֧yţ ywòsé֣p lehábá֗h ẇ⁠bé֤yţ ʻéşá̂w֙ lĕ⁠qa֔ş̌ wĕ⁠dálĕq֥ẇ bá⁠he֖m wa⁠ʼàkál֑ẇ⁠m wĕ⁠lòֽʼ-yiֽhĕye֤h şá̂riyd֙ lĕ⁠bé֣yţ ʻéşá̂֔w ki֥̇y yĕhwá֖h di̇béֽ̇r׃"],[1,19,"וְ⁠יָרְשׁ֨וּ הַ⁠נֶּ֜גֶב אֶת־הַ֣ר עֵשָׂ֗ו וְ⁠הַ⁠שְּׁפֵלָה֙ אֶת־פְּלִשְׁתִּ֔ים וְ⁠יָרְשׁוּ֙ אֶת־שְׂדֵ֣ה אֶפְרַ֔יִם וְ⁠אֵ֖ת שְׂדֵ֣ה שֹׁמְר֑וֹן וּ⁠בִנְיָמִ֖ן אֶת־הַ⁠גִּלְעָֽד׃","wĕ⁠yárĕş̌֨ẇ ha⁠nė֜geb ʼeţ-ha֣r ʻéşá̂֗w wĕ⁠ha⁠şĕ̇̌péláh֙ ʼeţ-pĕ̇lişĕ̌ţi̇֔ym wĕ⁠yárĕş̌ẇ֙ ʼeţ-şĕ̂dé֣h ʼepĕra֔yim wĕ⁠ʼé֖ţ şĕ̂dé֣h şò̌mĕr֑wòn ẇ⁠binĕyámi֖n ʼeţ-ha⁠gi̇lĕʻáֽd׃"],[1,20,"וְ⁠גָלֻ֣ת הַֽ⁠חֵל־הַ֠⁠זֶּה לִ⁠בְנֵ֨י יִשְׂרָאֵ֤ל אֲשֶֽׁר־כְּנַעֲנִים֙ עַד־צָ֣רְפַ֔ת וְ⁠גָלֻ֥ת יְרוּשָׁלִַ֖ם אֲשֶׁ֣ר בִּ⁠סְפָרַ֑ד יִֽרְשׁ֕וּ אֵ֖ת עָרֵ֥י הַ⁠נֶּֽגֶב׃","wĕ⁠gálu֣ţ haֽ⁠ẖél-ha֠⁠zėh li⁠bĕné֨y yişĕ̂ráʼé֤l ʼàşěֽr-kĕ̇naʻàniym֙ ʻad-ẕá֣rĕpa֔ţ wĕ⁠gálu֥ţ yĕrẇşá̌lia֖m ʼàşě֣r bi̇⁠sĕpára֑d yiֽrĕş̌֕ẇ ʼé֖ţ ʻáré֥y ha⁠nėֽgeb׃"],[1,21,"וְ⁠עָל֤וּ מֽוֹשִׁעִים֙ בְּ⁠הַ֣ר צִיּ֔וֹן לִ⁠שְׁפֹּ֖ט אֶת־הַ֣ר עֵשָׂ֑ו וְ⁠הָיְתָ֥ה לַֽ⁠יהוָ֖ה הַ⁠מְּלוּכָֽה׃","wĕ⁠ʻál֤ẇ mֽwòşǐʻiym֙ bĕ̇⁠ha֣r ẕiẏ֔wòn li⁠şĕ̌pò֖̇t ʼeţ-ha֣r ʻéşá֑̂w wĕ⁠háyĕţá֥h laֽ⁠yhwá֖h ha⁠mĕ̇lẇkáֽh׃"]],"fra-lsg1910":[[1,1,"Prophétie d'Abdias. Ainsi parle le Seigneur, l'Éternel, sur Édom: -Nous avons appris une nouvelle de la part de l'Éternel, Et un messager a été envoyé parmi les nations: Levez-vous, marchons contre Édom pour lui faire la guerre! -","Prophétie d'Abdias. Ainsi parle le Seigneur, l'Éternel, sur Édom: -Nous avons appris une nouvelle de la part de l'Éternel, Et un messager a été envoyé parmi les nations: Levez-vous, marchons contre Édom pour lui faire la guerre! -"],[1,2,"Voici, je te rendrai petit parmi les nations, Tu seras l'objet du plus grand mépris.","Voici, je te rendrai petit parmi les nations, Tu seras l'objet du plus grand mépris."],[1,3,"L'orgueil de ton coeur t'a égaré, Toi qui habites le creux des rochers, Qui t'assieds sur les hauteurs, Et qui dis en toi-même: Qui me précipitera jusqu'à terre?","L'orgueil de ton coeur t'a égaré, Toi qui habites le creux des rochers, Qui t'assieds sur les hauteurs, Et qui dis en toi-même: Qui me précipitera jusqu'à terre?"],[1,4,"Quand tu placerais ton nid aussi haut que celui de l'aigle, Quand tu le placerais parmi les étoiles, Je t'en précipiterai, dit l'Éternel.","Quand tu placerais ton nid aussi haut que celui de l'aigle, Quand tu le placerais parmi les étoiles, Je t'en précipiterai, dit l'Éternel."],[1,5,"Si des voleurs, des pillards, viennent de nuit chez toi, Comme te voilà dévasté! Mais enlèvent-ils plus qu'ils ne peuvent? Si des vendangeurs viennent chez toi, Ne laissent-ils rien à grappiller?...","Si des voleurs, des pillards, viennent de nuit chez toi, Comme te voilà dévasté! Mais enlèvent-ils plus qu'ils ne peuvent? Si des vendangeurs viennent chez toi, Ne laissent-ils rien à grappiller?..."],[1,6,"Ah! comme Ésaü est fouillé! Comme ses trésors sont découverts!","Ah! comme Ésaü est fouillé! Comme ses trésors sont découverts!"],[1,7,"Tous tes alliés t'ont chassé jusqu'à la frontière, Tes amis t'ont joué, t'ont dominé, Ceux qui mangeaient ton pain t'ont dressé des pièges, Et tu n'as pas su t'en apercevoir!","Tous tes alliés t'ont chassé jusqu'à la frontière, Tes amis t'ont joué, t'ont dominé, Ceux qui mangeaient ton pain t'ont dressé des pièges, Et tu n'as pas su t'en apercevoir!"],[1,8,"N'est-ce pas en ce jour, dit l'Éternel, Que je ferai disparaître d'Édom les sages, Et de la montagne d'Ésaü l'intelligence?","N'est-ce pas en ce jour, dit l'Éternel, Que je ferai disparaître d'Édom les sages, Et de la montagne d'Ésaü l'intelligence?"],[1,9,"Tes guerriers, ô Théman, seront dans l'épouvante, Car tous ceux de la montagne d'Ésaü périront dans le carnage.","Tes guerriers, ô Théman, seront dans l'épouvante, Car tous ceux de la montagne d'Ésaü périront dans le carnage."],[1,10,"À cause de ta violence contre ton frère Jacob, Tu seras couvert de honte, Et tu seras exterminé pour toujours.","À cause de ta violence contre ton frère Jacob, Tu seras couvert de honte, Et tu seras exterminé pour toujours."],[1,11,"Le jour où tu te tenais en face de lui, Le jour où des étrangers emmenaient captive son armée, Où des étrangers entraient dans ses portes, Et jetaient le sort sur Jérusalem, Toi aussi tu étais comme l'un d'eux.","Le jour où tu te tenais en face de lui, Le jour où des étrangers emmenaient captive son armée, Où des étrangers entraient dans ses portes, Et jetaient le sort sur Jérusalem, Toi aussi tu étais comme l'un d'eux."],[1,12,"Ne repais pas ta vue du jour de ton frère, du jour de son malheur, Ne te réjouis pas sur les enfants de Juda au jour de leur ruine, Et n'ouvre pas une grande bouche au jour de la détresse!","Ne repais pas ta vue du jour de ton frère, du jour de son malheur, Ne te réjouis pas sur les enfants de Juda au jour de leur ruine, Et n'ouvre pas une grande bouche au jour de la détresse!"],[1,13,"N'entre pas dans les portes de mon peuple au jour de sa ruine, Ne repais pas ta vue de son malheur au jour de sa ruine, Et ne porte pas la main sur ses richesses au jour de sa ruine!","N'entre pas dans les portes de mon peuple au jour de sa ruine, Ne repais pas ta vue de son malheur au jour de sa ruine, Et ne porte pas la main sur ses richesses au jour de sa ruine!"],[1,14,"Ne te tiens pas au carrefour pour exterminer ses fuyards, Et ne livre pas ses réchappés au jour de la détresse!","Ne te tiens pas au carrefour pour exterminer ses fuyards, Et ne livre pas ses réchappés au jour de la détresse!"],[1,15,"Car le jour de l'Éternel est proche, pour toutes les nations; Il te sera fait comme tu as fait, Tes oeuvres retomberont sur ta tête.","Car le jour de l'Éternel est proche, pour toutes les nations; Il te sera fait comme tu as fait, Tes oeuvres retomberont sur ta tête."],[1,16,"Car, comme vous avez bu sur ma montagne sainte, Ainsi toutes les nations boiront sans cesse; Elles boiront, elles avaleront, Et elles seront comme si elles n'avaient jamais été.","Car, comme vous avez bu sur ma montagne sainte, Ainsi toutes les nations boiront sans cesse; Elles boiront, elles avaleront, Et elles seront comme si elles n'avaient jamais été."],[1,17,"Mais le salut sera sur la montagne de Sion, elle sera sainte, Et la maison de Jacob reprendra ses possessions.","Mais le salut sera sur la montagne de Sion, elle sera sainte, Et la maison de Jacob reprendra ses possessions."],[1,18,"La maison de Jacob sera un feu, et la maison de Joseph une flamme; Mais la maison d'Ésaü sera du chaume, Qu'elles allumeront et consumeront; Et il ne restera rien de la maison d'Ésaü, Car l'Éternel a parlé.","La maison de Jacob sera un feu, et la maison de Joseph une flamme; Mais la maison d'Ésaü sera du chaume, Qu'elles allumeront et consumeront; Et il ne restera rien de la maison d'Ésaü, Car l'Éternel a parlé."],[1,19,"Ceux du midi posséderont la montagne d'Ésaü, Et ceux de la plaine le pays des Philistins; Ils posséderont le territoire d'Éphraïm et celui de Samarie; Et Benjamin possédera Galaad.","Ceux du midi posséderont la montagne d'Ésaü, Et ceux de la plaine le pays des Philistins; Ils posséderont le territoire d'Éphraïm et celui de Samarie; Et Benjamin possédera Galaad."],[1,20,"Les captifs de cette armée des enfants d'Israël Posséderont le pays occupé par les Cananéens jusqu'à Sarepta, Et les captifs de Jérusalem qui sont à Sepharad Posséderont les villes du midi.","Les captifs de cette armée des enfants d'Israël Posséderont le pays occupé par les Cananéens jusqu'à Sarepta, Et les captifs de Jérusalem qui sont à Sepharad Posséderont les villes du midi."],[1,21,"Des libérateurs monteront sur la montagne de Sion, Pour juger la montagne d'Ésaü; Et à l'Éternel appartiendra le règne.","Des libérateurs monteront sur la montagne de Sion, Pour juger la montagne d'Ésaü; Et à l'Éternel appartiendra le règne."]],"spa-rv1909":[[1,1,"VISIÓNde Abdías. El SeñorJehováha dichoasícuanto á Edom: Oídohemos el pregónde Jehová, y mensajeroes enviadoá las gentes. Levantaos, y levantémonoscontraella en batalla.","VISIÓNde Abdías. El SeñorJehováha dichoasícuanto á Edom: Oídohemos el pregónde Jehová, y mensajeroes enviadoá las gentes. Levantaos, y levantémonoscontraella en batalla."],[1,2,"He aquí, pequeñotehe hechoentre las gentes; abatidoeres tú en granmanera.","He aquí, pequeñotehe hechoentre las gentes; abatidoeres tú en granmanera."],[1,3,"La soberbiade tu corazónte ha engañado, tú que morasen las hendidurasde las peñas, en tu altísimamorada; que dicesen tu corazón: ¿Quiénme derribaráá tierra?","La soberbiade tu corazónte ha engañado, tú que morasen las hendidurasde las peñas, en tu altísimamorada; que dicesen tu corazón: ¿Quiénme derribaráá tierra?"],[1,4,"Site encaramarescomo águila, y sientrelas estrellaspusierestu nido, de ahíte derribaré, diceJehová.","Site encaramarescomo águila, y sientrelas estrellaspusierestu nido, de ahíte derribaré, diceJehová."],[1,5,"Siladronesvinieran á ti, órobadoresde noche(¡cómohas sido destruído!) ¿nohurtaranlo que les bastase? Pues sientraraná ti vendimiadores, aun dejaran algún rebusco.","Siladronesvinieran á ti, órobadoresde noche(¡cómohas sido destruído!) ¿nohurtaranlo que les bastase? Pues sientraraná ti vendimiadores, aun dejaran algún rebusco."],[1,6,"¡Cómofueron escudriñadaslas cosas deEsaú! sus cosas escondidasfueron buscadas.","¡Cómofueron escudriñadaslas cosas deEsaú! sus cosas escondidasfueron buscadas."],[1,7,"Hastael términote hicieron llegartodostus aliados; te han engañadotus pacíficos, prevalecieroncontra ti; los que comíantu pan, pusieronel lazodebajode ti: nohay en él entendimiento.","Hastael términote hicieron llegartodostus aliados; te han engañadotus pacíficos, prevalecieroncontra ti; los que comíantu pan, pusieronel lazodebajode ti: nohay en él entendimiento."],[1,8,"¿Noharé que perezcanen aquel día, diceJehová, los sabiosde Edom, y la prudenciadel montede Esaú?","¿Noharé que perezcanen aquel día, diceJehová, los sabiosde Edom, y la prudenciadel montede Esaú?"],[1,9,"Y tus valientes, oh Temán, serán quebrantados; porque todo hombreserá taladodel montede Esaúpor el estrago.","Y tus valientes, oh Temán, serán quebrantados; porque todo hombreserá taladodel montede Esaúpor el estrago."],[1,10,"Por la injuriade tu hermanoJacobte cubrirávergüenza, y serás taladopara siempre.","Por la injuriade tu hermanoJacobte cubrirávergüenza, y serás taladopara siempre."],[1,11,"El díaque estandotúdelante, llevaban extrañoscautivosu ejército, y los extrañosentrabanpor sus puertas, y echabansuertessobreJerusalem, tútambiéneras como unode ellos.","El díaque estandotúdelante, llevaban extrañoscautivosu ejército, y los extrañosentrabanpor sus puertas, y echabansuertessobreJerusalem, tútambiéneras como unode ellos."],[1,12,"Pues nodebiste tú estar mirandoen el díade tu hermano, el díaen que fué extrañado: note habías de haber alegradode los hijosde Judáen el díaque se perdieron, nihabías de ensanchar tu boca en el díade la angustia:","Pues nodebiste tú estar mirandoen el díade tu hermano, el díaen que fué extrañado: note habías de haber alegradode los hijosde Judáen el díaque se perdieron, nihabías de ensanchar tu boca en el díade la angustia:"],[1,13,"Nohabías de haber entradopor la puertade mi puebloen el díade su quebrantamiento; no, nohabías tú de haber miradosu malel díade su quebranto, ni haberechadomanoá sus bienesel díade su calamidad.","Nohabías de haber entradopor la puertade mi puebloen el díade su quebrantamiento; no, nohabías tú de haber miradosu malel díade su quebranto, ni haberechadomanoá sus bienesel díade su calamidad."],[1,14,"Tampocohabías de haberte paradoenlas encrucijadas, para matarlos que de ellos escapasen; ni habías tú de haber entregadolos que quedabanenel díade angustia.","Tampocohabías de haberte paradoenlas encrucijadas, para matarlos que de ellos escapasen; ni habías tú de haber entregadolos que quedabanenel díade angustia."],[1,15,"Porquecercanoestá el díade Jehovásobretodaslas gentes: como tú hicistese harácontigo: tu galardón volverásobretu cabeza.","Porquecercanoestá el díade Jehovásobretodaslas gentes: como tú hicistese harácontigo: tu galardón volverásobretu cabeza."],[1,16,"Dela manera que vosotros bebisteisenmi santomonte, beberántodaslas gentesdecontinuo; beberán, y engullirán, y seráncomo si nohubieran sido.","Dela manera que vosotros bebisteisenmi santomonte, beberántodaslas gentesdecontinuo; beberán, y engullirán, y seráncomo si nohubieran sido."],[1,17,"Mas en el montede Siónhabrásalvamento, y serásantidad, y la casade Jacob, poseerásus posesiones.","Mas en el montede Siónhabrásalvamento, y serásantidad, y la casade Jacob, poseerásus posesiones."],[1,18,"Y la casade Jacobseráfuego, y la casade Joséserállama, y la casade Esaúestopa, y los quemarán, y los consumirán; niaun reliquia quedaráen la casade Esaú, porqueJehoválo habló.","Y la casade Jacobseráfuego, y la casade Joséserállama, y la casade Esaúestopa, y los quemarán, y los consumirán; niaun reliquia quedaráen la casade Esaú, porqueJehoválo habló."],[1,19,"Y los del mediodíaposeeránel montede Esaú, y los llanos de los Palestinos; poseerántambién los camposde Ephraim, y los camposde Samaria; y Benjamíná Galaad.","Y los del mediodíaposeeránel montede Esaú, y los llanos de los Palestinos; poseerántambién los camposde Ephraim, y los camposde Samaria; y Benjamíná Galaad."],[1,20,"Y los cautivosde aqueste ejércitode los hijosde Israelposeeránlode los CananeoshastaSarepta; y los cautivosde Jerusalem, queestán en Sepharad, poseeránlas ciudadesdel mediodía.","Y los cautivosde aqueste ejércitode los hijosde Israelposeeránlode los CananeoshastaSarepta; y los cautivosde Jerusalem, queestán en Sepharad, poseeránlas ciudadesdel mediodía."],[1,21,"Y vendránsalvadoresal montede Siónpara juzgaral montede Esaú; y el reinoseráde Jehová.","Y vendránsalvadoresal montede Siónpara juzgaral montede Esaú; y el reinoseráde Jehová."]],"rus-synodal":[[1,1,"Видение Авдия. Так говорит Господь Бог о Едоме: весть услышали мы от Господа, и посол послан объявить народам: «вставайте, и выступим против него войною!»","Videnie Avdiâ. Tak govorit Gospodʹ Bog o Edome: vestʹ uslyšali my ot Gospoda, i posol poslan obʺâvitʹ narodam: «vstavajte, i vystupim protiv nego vojnoû!»"],[1,2,"Вот, Я сделал тебя малым между народами, и ты в большом презрении.","Vot, Â sdelal tebâ malym meždu narodami, i ty v bolʹšom prezrenii."],[1,3,"Гордость сердца твоего обольстила тебя; ты живешь в расселинах скал, на возвышенном месте, и говоришь в сердце твоем: «кто низринет меня на землю?»","Gordostʹ serdca tvoego obolʹstila tebâ; ty živešʹ v rasselinah skal, na vozvyšennom meste, i govorišʹ v serdce tvoem: «kto nizrinet menâ na zemlû?»"],[1,4,"Но хотя бы ты, как орел, поднялся высоко и среди звезд устроил гнездо твое, то и оттуда Я низрину тебя, говорит Господь.","No hotâ by ty, kak orel, podnâlsâ vysoko i sredi zvezd ustroil gnezdo tvoe, to i ottuda Â nizrinu tebâ, govorit Gospodʹ."],[1,5,"Не воры ли приходили к тебе? не ночные ли грабители, что ты так разорен? Но они украли бы столько, сколько надобно им. Если бы проникли к тебе обиратели винограда, то и они разве не оставили бы несколько ягод?","Ne vory li prihodili k tebe? ne nočnye li grabiteli, čto ty tak razoren? No oni ukrali by stolʹko, skolʹko nadobno im. Esli by pronikli k tebe obirateli vinograda, to i oni razve ne ostavili by neskolʹko âgod?"],[1,6,"Как обобрано все у Исава и обысканы тайники его!","Kak obobrano vse u Isava i obyskany tajniki ego!"],[1,7,"До границы выпроводят тебя все союзники твои, обманут тебя, одолеют тебя живущие с тобою в мире, ядущие хлеб твой нанесут тебе удар. Нет в нем смысла!","Do granicy vyprovodât tebâ vse soûzniki tvoi, obmanut tebâ, odoleût tebâ živuŝie s toboû v mire, âduŝie hleb tvoj nanesut tebe udar. Net v nem smysla!"],[1,8,"Не в тот ли день это будет, говорит Господь, когда Я истреблю мудрых в Едоме и благоразумных на горе Исава?","Ne v tot li denʹ éto budet, govorit Gospodʹ, kogda Â istreblû mudryh v Edome i blagorazumnyh na gore Isava?"],[1,9,"Поражены будут страхом храбрецы твои, Феман, дабы все на горе Исава истреблены были убийством.","Poraženy budut strahom hrabrecy tvoi, Feman, daby vse na gore Isava istrebleny byli ubijstvom."],[1,10,"За притеснение брата твоего, Иакова, покроет тебя стыд и ты истреблен будешь навсегда.","Za pritesnenie brata tvoego, Iakova, pokroet tebâ styd i ty istreblen budešʹ navsegda."],[1,11,"В тот день, когда ты стоял напротив, в тот день, когда чужие уводили войско его в плен и иноплеменники вошли в ворота его и бросали жребий о Иерусалиме, ты был как один из них.","V tot denʹ, kogda ty stoâl naprotiv, v tot denʹ, kogda čužie uvodili vojsko ego v plen i inoplemenniki vošli v vorota ego i brosali žrebij o Ierusalime, ty byl kak odin iz nih."],[1,12,"Не следовало бы тебе злорадно смотреть на день брата твоего, на день отчуждения его; не следовало бы радоваться о сынах Иуды в день гибели их и расширять рот в день бедствия.","Ne sledovalo by tebe zloradno smotretʹ na denʹ brata tvoego, na denʹ otčuždeniâ ego; ne sledovalo by radovatʹsâ o synah Iudy v denʹ gibeli ih i rasširâtʹ rot v denʹ bedstviâ."],[1,13,"Не следовало бы тебе входить в ворота народа Моего в день несчастья его и даже смотреть на злополучие его в день погибели его, ни касаться имущества его в день бедствия его,","Ne sledovalo by tebe vhoditʹ v vorota naroda Moego v denʹ nesčastʹâ ego i daže smotretʹ na zlopolučie ego v denʹ pogibeli ego, ni kasatʹsâ imuŝestva ego v denʹ bedstviâ ego,"],[1,14,"ни стоять на перекрестках для убивания бежавших его, ни выдавать уцелевших из него в день бедствия.","ni stoâtʹ na perekrestkah dlâ ubivaniâ bežavših ego, ni vydavatʹ ucelevših iz nego v denʹ bedstviâ."],[1,15,"Ибо близок день Господень на все народы: как ты поступал, так поступлено будет и с тобою; воздаяние твое обратится на голову твою.","Ibo blizok denʹ Gospodenʹ na vse narody: kak ty postupal, tak postupleno budet i s toboû; vozdaânie tvoe obratitsâ na golovu tvoû."],[1,16,"Ибо как вы пили на святой горе Моей, так все народы всегда будут пить, будут пить, проглотят и будут, как бы их не было.","Ibo kak vy pili na svâtoj gore Moej, tak vse narody vsegda budut pitʹ, budut pitʹ, proglotât i budut, kak by ih ne bylo."],[1,17,"А на горе Сионе будет спасение, и будет она святынею; и дом Иакова получит во владение наследие свое.","A na gore Sione budet spasenie, i budet ona svâtyneû; i dom Iakova polučit vo vladenie nasledie svoe."],[1,18,"И дом Иакова будет огнем, и дом Иосифа – пламенем, а дом Исавов – соломою: зажгут его, и истребят его, и никого не останется из дома Исава: ибо Господь сказал это.","I dom Iakova budet ognem, i dom Iosifa – plamenem, a dom Isavov – solomoû: zažgut ego, i istrebât ego, i nikogo ne ostanetsâ iz doma Isava: ibo Gospodʹ skazal éto."],[1,19,"И завладеют те, которые к югу, горою Исава, а которые в долине, – Филистимлянами; и завладеют полем Ефрема и полем Самарии, а Вениамин завладеет Галаадом.","I zavladeût te, kotorye k ûgu, goroû Isava, a kotorye v doline, – Filistimlânami; i zavladeût polem Efrema i polem Samarii, a Veniamin zavladeet Galaadom."],[1,20,"И переселенные из войска сынов Израилевых завладеют землею Хананейскою до Сарепты, а переселенные из Иерусалима, находящиеся в Сефараде, получат во владение города южные.","I pereselennye iz vojska synov Izrailevyh zavladeût zemleû Hananejskoû do Sarepty, a pereselennye iz Ierusalima, nahodâŝiesâ v Sefarade, polučat vo vladenie goroda ûžnye."],[1,21,"И придут спасители на гору Сион, чтобы судить гору Исава, и будет царство Господа.","I pridut spasiteli na goru Sion, čtoby suditʹ goru Isava, i budet carstvo Gospoda."]],"cmn-cuv-hant":[[1,1,"俄巴底亞得了耶和華的默示。 論 以東說： 我從耶和華那裏聽見信息， 並有使者被差往列國去， 說：起來吧， 一同起來與 以東爭戰！","é bā dǐ yà dé le yé hé huá de mò shì. lùn yǐ dōng shuō： wǒ cóng yé hé huá nà lǐ tīng jiàn xìn xī， bìng yǒu shǐ zhě bèi chà wǎng liè guó qù， shuō： qǐ lái ba， yī tóng qǐ lái yǔ yǐ dōng zhēng zhàn！"],[1,2,"我使你－ 以東在列國中為最小的， 被人大大藐視。","wǒ shǐ nǐ－ yǐ dōng zài liè guó zhōng wèi zuì xiǎo de， bèi rén dà dà miǎo shì."],[1,3,"住在山穴中、居所在高處的啊， 你因狂傲自欺， 心裏說：誰能將我拉下地去呢？","zhù zài shān xué zhōng, jū suǒ zài gāo chù de a， nǐ yīn kuáng ào zì qī， xīn lǐ shuō： shuí néng jiāng wǒ lā xià de qù ne？"],[1,4,"你雖如大鷹高飛， 在星宿之間搭窩， 我必從那裏拉下你來。 這是耶和華說的。","nǐ suī rú dà yīng gāo fēi， zài xīng sù zhī jiān dā wō， wǒ bì cóng nà lǐ lā xià nǐ lái. zhè shì yé hé huá shuō de."],[1,5,"盜賊若來在你那裏， 或強盜夜間而來－ 你何竟被剪除－ 豈不偷竊直到夠了呢？ 摘葡萄的若來到你那裏， 豈不剩下些葡萄呢？","dào zéi ruò lái zài nǐ nà lǐ， huò qiáng dào yè jiān ér lái－ nǐ hé jìng bèi jiǎn chú－ qǐ bù tōu qiè zhí dào gòu le ne？ zhāi pú táo de ruò lái dào nǐ nà lǐ， qǐ bù shèng xià xiē pú táo ne？"],[1,6,"以掃 的隱密處何竟被搜尋？ 他隱藏的寶物何竟被查出？","yǐ sǎo de yǐn mì chù hé jìng bèi sōu xún？ tā yǐn cáng de bǎo wù hé jìng bèi chá chū？"],[1,7,"與你結盟的都送你上路，直到交界； 與你和好的欺騙你，且勝過你； 與你一同吃飯的設下網羅陷害你； 在你心裏毫無聰明。","yǔ nǐ jié méng de dōu sòng nǐ shàng lù， zhí dào jiāo jiè； yǔ nǐ hé hǎo de qī piàn nǐ， qiě shèng guò nǐ； yǔ nǐ yī tóng chī fàn de shè xià wǎng luó xiàn hài nǐ； zài nǐ xīn lǐ háo wú cōng míng."],[1,8,"耶和華說：到那日， 我豈不從 以東除滅智慧人？ 從 以掃山除滅聰明人？","yé hé huá shuō： dào nà rì， wǒ qǐ bù cóng yǐ dōng chú miè zhì huì rén？ cóng yǐ sǎo shān chú miè cōng míng rén？"],[1,9,"提幔哪， 你的勇士必驚惶， 甚至 以掃山的人都被殺戮剪除。","tí màn nǎ， nǐ de yǒng shì bì jīng huáng， shèn zhì yǐ sǎo shān de rén dōu bèi shā lù jiǎn chú."],[1,10,"因你向兄弟 雅各行強暴， 羞愧必遮蓋你， 你也必永遠斷絕。","yīn nǐ xiàng xiōng dì yǎ gè xíng qiáng bào， xiū kuì bì zhē gài nǐ， nǐ yě bì yǒng yuǎn duàn jué."],[1,11,"當外人擄掠 雅各的財物， 外邦人進入他的城門， 為 耶路撒冷拈鬮的日子， 你竟站在一旁，像與他們同夥。","dāng wài rén lǔ lüè yǎ gè de cái wù， wài bāng rén jìn rù tā de chéng mén， wèi yé lù sā lěng niān jiū de rì zǐ， nǐ jìng zhàn zài yī páng， xiàng yǔ tā men tóng huǒ."],[1,12,"你兄弟遭難的日子， 你不當瞪眼看着； 猶大人被滅的日子， 你不當因此歡樂； 他們遭難的日子， 你不當說狂傲的話。","nǐ xiōng dì zāo nán de rì zǐ， nǐ bù dāng dèng yǎn kàn zhe； yóu dà rén bèi miè de rì zǐ， nǐ bù dāng yīn cǐ huān lè； tā men zāo nán de rì zǐ， nǐ bù dāng shuō kuáng ào de huà."],[1,13,"我民遭災的日子， 你不當進他們的城門； 他們遭災的日子， 你不當瞪眼看着他們受苦； 他們遭災的日子， 你不當伸手搶他們的財物；","wǒ mín zāo zāi de rì zǐ， nǐ bù dāng jìn tā men de chéng mén； tā men zāo zāi de rì zǐ， nǐ bù dāng dèng yǎn kàn zhe tā men shòu kǔ； tā men zāo zāi de rì zǐ， nǐ bù dāng shēn shǒu qiǎng tā men de cái wù；"],[1,14,"你不當站在岔路口剪除他們中間逃脫的； 他們遭難的日子， 你不當將他們剩下的人交付 仇敵。","nǐ bù dāng zhàn zài chà lù kǒu jiǎn chú tā men zhōng jiān táo tuō de； tā men zāo nán de rì zǐ， nǐ bù dāng jiāng tā men shèng xià de rén jiāo fù chóu dí."],[1,15,"耶和華降罰的日子臨近萬國。 你怎樣行， 他也必照樣向你行； 你的報應必歸到你頭上。","yé hé huá jiàng fá de rì zǐ lín jìn wàn guó. nǐ zěn yàng xíng， tā yě bì zhào yàng xiàng nǐ xíng； nǐ de bào yīng bì guī dào nǐ tóu shàng."],[1,16,"你們 猶大人在我聖山怎樣喝了 苦杯， 萬國也必照樣常常地喝； 且喝且咽，他們就歸於無有。","nǐ men yóu dà rén zài wǒ shèng shān zěn yàng hē le kǔ bēi， wàn guó yě bì zhào yàng cháng cháng de hē； qiě hē qiě yàn， tā men jiù guī yú wú yǒu."],[1,17,"在 錫安山必有逃脫的人， 那山也必成聖； 雅各家必得原有的產業。","zài xī ān shān bì yǒu táo tuō de rén， nà shān yě bì chéng shèng； yǎ gè jiā bì dé yuán yǒu de chǎn yè."],[1,18,"雅各家必成為大火； 約瑟家必為火焰； 以掃家必如碎詡； 火必將他燒着吞滅。 以掃家必無餘剩的。 這是耶和華說的。","yǎ gè jiā bì chéng wèi dà huǒ； yuē sè jiā bì wèi huǒ yàn； yǐ sǎo jiā bì rú suì xǔ； huǒ bì jiāng tā shāo zhe tūn miè. yǐ sǎo jiā bì wú yú shèng de. zhè shì yé hé huá shuō de."],[1,19,"南地的人必得 以掃山； 高原的人必得 非利士地， 也得 以法蓮地和 撒馬利亞地； 便雅憫人必得 基列。","nán de de rén bì dé yǐ sǎo shān； gāo yuán de rén bì dé fēi lì shì de， yě dé yǐ fǎ lián de hé sā mǎ lì yà de； biàn yǎ mǐn rén bì dé jī liè."],[1,20,"在 迦南人中被擄的 以色列眾人 必得地直到 撒勒法； 在 西法拉中被擄的 耶路撒冷人 必得南地的城邑。","zài jiā nán rén zhōng bèi lǔ de yǐ sè liè zhòng rén bì dé de zhí dào sā lēi fǎ； zài xī fǎ lā zhōng bèi lǔ de yé lù sā lěng rén bì dé nán de de chéng yì."],[1,21,"必有拯救者上到 錫安山，審判 以掃山； 國度就歸耶和華了。","bì yǒu zhěng jiù zhě shàng dào xī ān shān， shěn pàn yǐ sǎo shān； guó dù jiù guī yé hé huá le."]],"arb-vandyck":[[1,1,"رُؤْيَا عُوبَدْيَا: هَكَذَا قَالَ ٱلسَّيِّدُ ٱلرَّبُّ عَنْ أَدُومَ: سَمِعْنَا خَبَرًا مِنْ قِبَلِ ٱلرَّبِّ وَأُرْسِلَ رَسُولٌ بَيْنَ ٱلْأُمَمِ: «قُومُوا، وَلْنَقُمْ عَلَيْهَا لِلْحَرْبِ».","rū̊̉yā ʿūbad̊yā: hakadẖā qāla ٱlsãyĩdu ٱlrãbũ ʿan̊ ạảdūma: samiʿ̊nā kẖabaraⁿạ min̊ qibali ٱlrãbĩ wāủr̊sila rasūluⁿ baẙna ٱl̊ạủmami: «qūmūạ, wal̊naqum̊ ʿalaẙhā lil̊ḥar̊bi»."],[1,2,"«إِنِّي قَدْ جَعَلْتُكَ صَغِيرًا بَيْنَ ٱلْأُمَمِ. أَنْتَ مُحْتَقَرٌ جِدًّا.","«ại̹nĩy qad̊ jaʿal̊tuka ṣagẖīraⁿạ baẙna ٱl̊ạủmami. ạản̊ta muḥ̊taqaruⁿ jidaⁿ̃ạ."],[1,3,"تَكَبُّرُ قَلْبِكَ قَدْ خَدَعَكَ أَيُّهَا ٱلسَّاكِنُ فِي مَحَاجِئِ ٱلصَّخْرِ، رِفْعَةَ مَقْعَدِهِ، ٱلْقَائِلُ فِي قَلْبِهِ: مَنْ يُحْدِرُنِي إِلَى ٱلْأَرْضِ؟","takabũru qal̊bika qad̊ kẖadaʿaka ạảyũhā ٱlsãạkinu fī maḥājīỉ ٱlṣãkẖ̊ri, rif̊ʿaẗa maq̊ʿadihi, ٱl̊qāyỉlu fī qal̊bihi: man̊ yuḥ̊dirunī ại̹lay̱ ٱl̊ạảr̊ḍi?"],[1,4,"إِنْ كُنْتَ تَرْتَفِعُ كَٱلنَّسْرِ، وَإِنْ كَانَ عُشُّكَ مَوْضُوعًا بَيْنَ ٱلنُّجُومِ، فَمِنْ هُنَاكَ أُحْدِرُكَ، يَقُولُ ٱلرَّبُّ.","ại̹n̊ kun̊ta tar̊tafiʿu kaٱlnãs̊ri, wāi̹n̊ kāna ʿusẖũka maẘḍūʿaⁿạ baẙna ٱlnũjūmi, famin̊ hunāka ạủḥ̊diruka, yaqūlu ٱlrãbũ."],[1,5,"إِنْ أَتَاكَ سَارِقُونَ أَوْ لُصُوصُ لَيْلٍ. كَيْفَ هَلِكْتَ! أَفَلَا يَسْرِقُونَ حَاجَتَهُمْ؟ إِنْ أَتَاكَ قَاطِفُونَ أَفَلَا يُبْقُونَ خُصَاصَةً؟","ại̹n̊ ạảtāka sāriqūna ạảẘ luṣūṣu laẙliⁿ. kaẙfa halik̊ta! ạảfalā yas̊riqūna ḥājatahum̊? ại̹n̊ ạảtāka qāṭifūna ạảfalā yub̊qūna kẖuṣāṣaẗaⁿ?"],[1,6,"كَيْفَ فُتِّشَ عِيسُو وَفُحِصَتْ مَخَابِئُهُ؟","kaẙfa futĩsẖa ʿīsū wafuḥiṣat̊ makẖābīủhu?"],[1,7,"طَرَدَكَ إِلَى ٱلتُّخْمِ كُلُّ مُعَاهِدِيكَ. خَدَعَكَ وَغَلَبَ عَلَيْكَ مُسَالِمُوكَ. أَهْلُ خُبْزِكَ وَضَعُوا شَرَكًا تَحْتَكَ. لَا فَهْمَ فِيهِ.","ṭaradaka ại̹lay̱ ٱltũkẖ̊mi kulũ muʿāhidīka. kẖadaʿaka wagẖalaba ʿalaẙka musālimūka. ạảh̊lu kẖub̊zika waḍaʿūạ sẖarakaⁿạ taḥ̊taka. lā fah̊ma fīhi."],[1,8,"أَلَا أُبِيدُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، ٱلْحُكَمَاءَ مِنْ أَدُومَ، وَٱلْفَهْمَ مِنْ جَبَلِ عِيسُو؟","ạảlā ạủbīdu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ٱl̊ḥukamāʾa min̊ ạảdūma, waٱl̊fah̊ma min̊ jabali ʿīsū?"],[1,9,"فَيَرْتَاعُ أَبْطَالُكَ يَا تَيْمَانُ، لِكَيْ يَنْقَرِضَ كُلُّ وَاحِدٍ مِنْ جَبَلِ عِيسُو بِٱلْقَتْلِ.","fayar̊tāʿu ạảb̊ṭāluka yā taẙmānu, likaẙ yan̊qariḍa kulũ wāḥidiⁿ min̊ jabali ʿīsū biٱl̊qat̊li."],[1,10,"«مِنْ أَجْلِ ظُلْمِكَ لِأَخِيكَ يَعْقُوبَ، يَغْشَاكَ ٱلْخِزْيُ وَتَنْقَرِضُ إِلَى ٱلْأَبَدِ.","«min̊ ạảj̊li ẓul̊mika liạảkẖīka yaʿ̊qūba, yagẖ̊sẖāka ٱl̊kẖiz̊yu watan̊qariḍu ại̹lay̱ ٱl̊ạảbadi."],[1,11,"يَوْمَ وَقَفْتَ مُقَابِلَهُ يَوْمَ سَبَتِ ٱلْأَعَاجِمُ قُدْرَتَهُ، وَدَخَلَتِ ٱلْغُرَبَاءُ أَبْوَابَهُ، وَأَلْقَوْا قُرْعَةً عَلَى أُورُشَلِيمَ، كُنْتَ أَنْتَ أَيْضًا كَوَاحِدٍ مِنْهُمْ.","yaẘma waqaf̊ta muqābilahu yaẘma sabati ٱl̊ạảʿājimu qud̊ratahu, wadakẖalati ٱl̊gẖurabāʾu ạảb̊wābahu, wāảl̊qaẘạ qur̊ʿaẗaⁿ ʿalay̱ ạủwrusẖalīma, kun̊ta ạản̊ta ạảẙḍaⁿạ kawāḥidiⁿ min̊hum̊."],[1,12,"وَيَجِبُ أَنْ لَا تَنْظُرَ إِلَى يَوْمِ أَخِيكَ يَوْمَ مُصِيبَتِهِ، وَلَا تَشْمَتَ بِبَنِي يَهُوذَا يَوْمَ هَلَاكِهِمْ، وَلَا تَفْغَرَ فَمَكَ يَوْمَ ٱلضِّيقِ،","wayajibu ạản̊ lā tan̊ẓura ại̹lay̱ yaẘmi ạảkẖīka yaẘma muṣībatihi, walā tasẖ̊mata bibanī yahūdẖā yaẘma halākihim̊, walā taf̊gẖara famaka yaẘma ٱlḍĩyqi,"],[1,13,"وَلَا تَدْخُلَ بَابَ شَعْبِي يَوْمَ بَلِيَّتِهِمْ، وَلَا تَنْظُرَ أَنْتَ أَيْضًا إِلَى مُصِيبَتِهِ يَوْمَ بَلِيَّتِهِ، وَلَا تَمُدَّ يَدًا إِلَى قُدْرَتِهِ يَوْمَ بَلِيَّتِهِ،","walā tad̊kẖula bāba sẖaʿ̊bī yaẘma balīãtihim̊, walā tan̊ẓura ạản̊ta ạảẙḍaⁿạ ại̹lay̱ muṣībatihi yaẘma balīãtihi, walā tamudã yadaⁿạ ại̹lay̱ qud̊ratihi yaẘma balīãtihi,"],[1,14,"وَلَا تَقِفَ عَلَى ٱلْمَفْرَقِ لِتَقْطَعَ مُنْفَلِتِيهِ، وَلَا تُسَلِّمَ بَقَايَاهُ يَوْمَ ٱلضِّيقِ.","walā taqifa ʿalay̱ ٱl̊maf̊raqi litaq̊ṭaʿa mun̊falitīhi, walā tusalĩma baqāyāhu yaẘma ٱlḍĩyqi."],[1,15,"فَإِنَّهُ قَرِيبٌ يَوْمُ ٱلرَّبِّ عَلَى كُلِّ ٱلْأُمَمِ. كَمَا فَعَلْتَ يُفْعَلُ بِكَ. عَمَلُكَ يَرْتَدُّ عَلَى رَأْسِكَ.","fāi̹nãhu qarībuⁿ yaẘmu ٱlrãbĩ ʿalay̱ kulĩ ٱl̊ạủmami. kamā faʿal̊ta yuf̊ʿalu bika. ʿamaluka yar̊tadũ ʿalay̱ rā̊̉sika."],[1,16,"لِأَنَّهُ كَمَا شَرِبْتُمْ عَلَى جَبَلِ قُدْسِي، يَشْرَبُ جَمِيعُ ٱلْأُمَمِ دَائِمًا، يَشْرَبُونَ وَيَجْرَعُونَ وَيَكُونُونَ كَأَنَّهُمْ لَمْ يَكُونُوا.","liạảnãhu kamā sẖarib̊tum̊ ʿalay̱ jabali qud̊sī, yasẖ̊rabu jamīʿu ٱl̊ạủmami dāyỉmaⁿạ, yasẖ̊rabūna wayaj̊raʿūna wayakūnūna kāảnãhum̊ lam̊ yakūnūạ."],[1,17,"«وَأَمَّا جَبَلُ صِهْيَوْنَ فَتَكُونُ عَلَيْهِ نَجَاةٌ، وَيَكُونُ مُقَدَّسًا، وَيَرِثُ بَيْتُ يَعْقُوبَ مَوَارِيثَهُمْ.","«wāảmãạ jabalu ṣih̊yaẘna fatakūnu ʿalaẙhi najāẗuⁿ, wayakūnu muqadãsaⁿạ, wayaritẖu baẙtu yaʿ̊qūba mawārītẖahum̊."],[1,18,"وَيَكُونُ بَيْتُ يَعْقُوبَ نَارًا، وَبَيْتُ يُوسُفَ لَهِيبًا، وَبَيْتُ عِيسُو قَشًّا، فَيُشْعِلُونَهُمْ وَيَأْكُلُونَهُمْ وَلَا يَكُونُ بَاقٍ مِنْ بَيْتِ عِيسُو، لِأَنَّ ٱلرَّبَّ تَكَلَّمَ».","wayakūnu baẙtu yaʿ̊qūba nāraⁿạ, wabaẙtu yūsufa lahībaⁿạ, wabaẙtu ʿīsū qasẖaⁿ̃ạ, fayusẖ̊ʿilūnahum̊ wayā̊̉kulūnahum̊ walā yakūnu bāqiⁿ min̊ baẙti ʿīsū, liạảnã ٱlrãbã takalãma»."],[1,19,"وَيَرِثُ أَهْلُ ٱلْجَنُوبِ جَبَلَ عِيسُو، وَأَهْلُ ٱلسَّهْلِ ٱلْفِلِسْطِينِيِّينَ، وَيَرِثُونَ بِلَادَ أَفْرَايِمَ وَبِلَادَ ٱلسَّامِرَةِ، وَيَرِثُ بَنْيَامِينُ جِلْعَادَ.","wayaritẖu ạảh̊lu ٱl̊janūbi jabala ʿīsū, wāảh̊lu ٱlsãh̊li ٱl̊filis̊ṭīnīĩyna, wayaritẖūna bilāda ạảf̊rāyima wabilāda ٱlsãạmiraẗi, wayaritẖu ban̊yāmīnu jil̊ʿāda."],[1,20,"وَسَبْيُ هَذَا ٱلْجَيْشِ مِنْ بَنِي إِسْرَائِيلَ يَرِثُونَ ٱلَّذِينَ هُمْ مِنَ ٱلْكَنْعَانِيِّينَ إِلَى صَرْفَةَ. وَسَبْيُ أُورُشَلِيمَ ٱلَّذِينَ فِي صَفَارِدَ يَرِثُونَ مُدُنَ ٱلْجَنُوبِ.","wasab̊yu hadẖā ٱl̊jaẙsẖi min̊ banī ại̹s̊rāyỉyla yaritẖūna ٱlãdẖīna hum̊ mina ٱl̊kan̊ʿānīĩyna ại̹lay̱ ṣar̊faẗa. wasab̊yu ạủwrusẖalīma ٱlãdẖīna fī ṣafārida yaritẖūna muduna ٱl̊janūbi."],[1,21,"وَيَصْعَدُ مُخَلِّصُونَ عَلَى جَبَلِ صِهْيَوْنَ لِيَدِينُوا جَبَلَ عِيسُو، وَيَكُونُ ٱلْمُلْكُ لِلرَّبِّ.","wayaṣ̊ʿadu mukẖalĩṣūna ʿalay̱ jabali ṣih̊yaẘna līadīnūạ jabala ʿīsū, wayakūnu ٱl̊mul̊ku lilrãbĩ."]],"bis-obbr":[[1,1,"Ol tok we i stap long buk ya, Hae God we i Masta* blong yumi i givim long Profet Obadaea, blong tokbaot ol man Edom. Nao Profet Obadaea i talem se, “Hae God i sanem wan man blong karem tok blong hem i go long olgeta kantri, mo mifala ol profet i harem tok ya blong hem. Hem i talem long olgeta se, ‘Naoia yufala i mas mekemrere blong yumi go faet long ol man Edom.’ ”","Ol tok we i stap long buk ya, Hae God we i Masta* blong yumi i givim long Profet Obadaea, blong tokbaot ol man Edom. Nao Profet Obadaea i talem se, “Hae God i sanem wan man blong karem tok blong hem i go long olgeta kantri, mo mifala ol profet i harem tok ya blong hem. Hem i talem long olgeta se, ‘Naoia yufala i mas mekemrere blong yumi go faet long ol man Edom.’ ”"],[1,2,"Mo Profet Obadaea i gohed i talemaot we Hae God i talem se, “Ol man Edom. Mi bambae mi mekem we paoa blong yufala i finis. Olgeta man bambae oli lukluk rabis long yufala.","Mo Profet Obadaea i gohed i talemaot we Hae God i talem se, “Ol man Edom. Mi bambae mi mekem we paoa blong yufala i finis. Olgeta man bambae oli lukluk rabis long yufala."],[1,3,"Yufala i praod tumas. Taon we i kaptel blong yufala, yufala i wokem long wan bigfala ston antap long bigfala hil, mo ol haos blong yufala oli stap antap long hil ya // we i hae we i hae. Nao from samting ya, yufala i stap tingting se bambae i no gat man i save pulumdaon yufala. Be ol tingting ya i blong giaman long yufala nomo.","Yufala i praod tumas. Taon we i kaptel blong yufala, yufala i wokem long wan bigfala ston antap long bigfala hil, mo ol haos blong yufala oli stap antap long hil ya // we i hae we i hae. Nao from samting ya, yufala i stap tingting se bambae i no gat man i save pulumdaon yufala. Be ol tingting ya i blong giaman long yufala nomo."],[1,4,"Nating we yufala i wokem ol haos blong yufala antap long hil we i antap olgeta, olsem nes blong bigfala pijin ya igel* we i putum antap olgeta, mo nating we ol haos ya oli antap olgeta klosap long ol sta, be mi bambae mi pulumdaon yufala bakegen.","Nating we yufala i wokem ol haos blong yufala antap long hil we i antap olgeta, olsem nes blong bigfala pijin ya igel* we i putum antap olgeta, mo nating we ol haos ya oli antap olgeta klosap long ol sta, be mi bambae mi pulumdaon yufala bakegen."],[1,5,"“Sipos man blong stil i kam long naet, hem i save stilim ol samting ya nomo we hem i wantem. Mo taem ol man oli stap tekemaot ol frut blong grep,* oltaem oli mas livim sam i stap long rop blong hem. Be taem ol enemi blong yufala oli kam, bambae oli kilim yufala evriwan i ded we oli no save livim wan i stap.","“Sipos man blong stil i kam long naet, hem i save stilim ol samting ya nomo we hem i wantem. Mo taem ol man oli stap tekemaot ol frut blong grep,* oltaem oli mas livim sam i stap long rop blong hem. Be taem ol enemi blong yufala oli kam, bambae oli kilim yufala evriwan i ded we oli no save livim wan i stap."],[1,6,"Ol man Edom. Yufala i laen blong Esao. Ol gudgudfala samting blong yufala, ol enemi bambae oli tektekemaot evriwan, oli karem i blong olgeta.","Ol man Edom. Yufala i laen blong Esao. Ol gudgudfala samting blong yufala, ol enemi bambae oli tektekemaot evriwan, oli karem i blong olgeta."],[1,7,"Ol fren blong yufala nomo, be bambae oli giaman long yufala, oli ronemaot yufala i gowe long ol graon blong yufala. Mo olgeta ya we naoia oli stap gud nomo wetem yufala, bambae oli winim yufala. Mo ol gudfala fren blong yufala we yufala i stap kakae wanples, bambae oli putum trap, blong yufala i fas long hem, mo bambae oli stap tokbaot yufala se, ‘?Wehem waes blong ol man ya we bifo oli flas tumas long hem?’","Ol fren blong yufala nomo, be bambae oli giaman long yufala, oli ronemaot yufala i gowe long ol graon blong yufala. Mo olgeta ya we naoia oli stap gud nomo wetem yufala, bambae oli winim yufala. Mo ol gudfala fren blong yufala we yufala i stap kakae wanples, bambae oli putum trap, blong yufala i fas long hem, mo bambae oli stap tokbaot yufala se, ‘?Wehem waes blong ol man ya we bifo oli flas tumas long hem?’"],[1,8,"“Ol man Edom. Long dei ya we bambae mi mi givim panis long yufala, bambae mi kilim olgeta waes man blong yufala, mo bambae i no moa gat waes long kantri blong yufala.","“Ol man Edom. Long dei ya we bambae mi mi givim panis long yufala, bambae mi kilim olgeta waes man blong yufala, mo bambae i no moa gat waes long kantri blong yufala."],[1,9,"Ol strong man blong yufala we oli stap long taon ya Teman, bambae oli seksek, oli fraet. Mo olgeta soldia blong yufala, bambae mi kilim olgeta evriwan i ded.”","Ol strong man blong yufala we oli stap long taon ya Teman, bambae oli seksek, oli fraet. Mo olgeta soldia blong yufala, bambae mi kilim olgeta evriwan i ded.”"],[1,10,"Nao Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Ol man Edom. Bambae yufala i sem bigwan. Mi bambae mi kilim yufala evriwan i ded, from we bifo, yufala i bin ravem ol brata ya blong yufala we oli laen* blong Isrel,* mo yufala i bin kilim olgeta tu.","Nao Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Ol man Edom. Bambae yufala i sem bigwan. Mi bambae mi kilim yufala evriwan i ded, from we bifo, yufala i bin ravem ol brata ya blong yufala we oli laen* blong Isrel,* mo yufala i bin kilim olgeta tu."],[1,11,"Bifo, taem ol strenja oli kam long Jerusalem,* oli brekem ol doa* blong stonwol blong taon ya, oli kam insaed, be yufala i stap lukluk nomo, yufala i no givhan nating long ol brata ya blong yufala. Fasin blong yufala i olsem fasin blong ol strenja ya stret, we oli kam insaed long Jerusalem, nao oli tekemaot ol gudgudfala samting blong ples ya, oli seraot long olgeta.","Bifo, taem ol strenja oli kam long Jerusalem,* oli brekem ol doa* blong stonwol blong taon ya, oli kam insaed, be yufala i stap lukluk nomo, yufala i no givhan nating long ol brata ya blong yufala. Fasin blong yufala i olsem fasin blong ol strenja ya stret, we oli kam insaed long Jerusalem, nao oli tekemaot ol gudgudfala samting blong ples ya, oli seraot long olgeta."],[1,12,"Ol man Juda* ya oli brata blong yufala. ?Be taem oli stap long trabol, from wanem yufala i laf nogud long olgeta? ?Taem ol enemi blong olgeta oli spolem ples blong olgeta, be yufala i harem gud from wanem? ?Taem oli harem nogud, be from wanem yufala i laf long olgeta?","Ol man Juda* ya oli brata blong yufala. ?Be taem oli stap long trabol, from wanem yufala i laf nogud long olgeta? ?Taem ol enemi blong olgeta oli spolem ples blong olgeta, be yufala i harem gud from wanem? ?Taem oli harem nogud, be from wanem yufala i laf long olgeta?"],[1,13,"?Long dei ya we trabol i kasem ol man ya blong mi mo oli stap harem nogud, be from wanem yufala i go insaed long taon blong olgeta, yufala i stap tekemaot ol gudgudfala samting blong olgeta, yufala i karem i blong yufala?","?Long dei ya we trabol i kasem ol man ya blong mi mo oli stap harem nogud, be from wanem yufala i go insaed long taon blong olgeta, yufala i stap tekemaot ol gudgudfala samting blong olgeta, yufala i karem i blong yufala?"],[1,14,"?From wanem yufala i stap wet long ples we ol rod i kros, blong holem olgeta we oli wantem ronwe? ?Olgeta oli harem nogud finis, be from wanem yufala i holem olgeta, yufala i givim olgeta i go long ol enemi blong olgeta?”","?From wanem yufala i stap wet long ples we ol rod i kros, blong holem olgeta we oli wantem ronwe? ?Olgeta oli harem nogud finis, be from wanem yufala i holem olgeta, yufala i givim olgeta i go long ol enemi blong olgeta?”"],[1,15,"Mo Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Ol man Edom. Mi mi Hae God, mo Dei* ya blong mi i stap kam klosap we mi bambae mi jajem olgeta kantri long hem. Fasin ya we yufala i mekem long ol man Juda,* bambae mi mekem sem fasin ya long yufala bakegen. Bambae yufala i kasem sem samting we yufala i bin mekem long olgeta.","Mo Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Ol man Edom. Mi mi Hae God, mo Dei* ya blong mi i stap kam klosap we mi bambae mi jajem olgeta kantri long hem. Fasin ya we yufala i mekem long ol man Juda,* bambae mi mekem sem fasin ya long yufala bakegen. Bambae yufala i kasem sem samting we yufala i bin mekem long olgeta."],[1,16,"Ol man Juda. Yufala i man blong mi. Yufala i kasem strong panis finis long tabu hil* blong mi, nao yufala i harem nogud from. Be ol narafala kantri we oli stap raonabaot long yufala, panis blong olgeta bambae i strong moa. Bambae oli kasem panis ya, nao oli go lus olgeta.”","Ol man Juda. Yufala i man blong mi. Yufala i kasem strong panis finis long tabu hil* blong mi, nao yufala i harem nogud from. Be ol narafala kantri we oli stap raonabaot long yufala, panis blong olgeta bambae i strong moa. Bambae oli kasem panis ya, nao oli go lus olgeta.”"],[1,17,"Mo Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Be long hil ya Saeon,* bambae i gat ol man we oli stap gud, oli sef, nao ples ya bambae i kam wan tabu ples. Ol laen* blong Isrel* bambae oli holem graon ya bakegen we i stret graon blong olgeta.","Mo Profet Obadaea i gohed, i talemaot we Hae God i talem se, “Be long hil ya Saeon,* bambae i gat ol man we oli stap gud, oli sef, nao ples ya bambae i kam wan tabu ples. Ol laen* blong Isrel* bambae oli holem graon ya bakegen we i stret graon blong olgeta."],[1,18,"“Ol laen ya blong Isrel we oli kamaot biaen long Josef mo ol narafala laen blong Isrel, bambae oli olsem faea. Bambae oli flatemgud ol laen blong Esao olsem we faea i flatemgud ol gras. Mo bambae i no gat wan man long laen blong hem i stap laef. Mi mi Hae God, mo hemia tok blong mi.","“Ol laen ya blong Isrel we oli kamaot biaen long Josef mo ol narafala laen blong Isrel, bambae oli olsem faea. Bambae oli flatemgud ol laen blong Esao olsem we faea i flatemgud ol gras. Mo bambae i no gat wan man long laen blong hem i stap laef. Mi mi Hae God, mo hemia tok blong mi."],[1,19,"“Olgeta man we oli stap long Juda* long saed i go long saot, bambae oli holem kantri ya Edom. Mo olgeta we oli stap long botom blong ol hil long wes, bambae oli holem kantri ya Filistia. Mo ol laen blong Isrel bambae oli holem ol ples ya long Efrem,* mo long Sameria.* Mo ol laen blong Benjamin,* bambae oli tekem ol graon ya long Gilead i blong olgeta.","“Olgeta man we oli stap long Juda* long saed i go long saot, bambae oli holem kantri ya Edom. Mo olgeta we oli stap long botom blong ol hil long wes, bambae oli holem kantri ya Filistia. Mo ol laen blong Isrel bambae oli holem ol ples ya long Efrem,* mo long Sameria.* Mo ol laen blong Benjamin,* bambae oli tekem ol graon ya long Gilead i blong olgeta."],[1,20,"Ol laen blong Isrel ya we bifo oli stap long kantri blong olgeta long not, mo we ol enemi oli kam tekemaot olgeta oli go stap wok slef* long ol narafala kantri, oli plante we plante. Be bambae olgeta oli kambak, oli winim ol ples long kantri ya Fonisia, go kasem taon ya Jarefat long not. Mo ol man Jerusalem* we oli stap wok slef long taon ya Sadis, bambae oli kam holem ol taon long Juda long saed i go long saot.","Ol laen blong Isrel ya we bifo oli stap long kantri blong olgeta long not, mo we ol enemi oli kam tekemaot olgeta oli go stap wok slef* long ol narafala kantri, oli plante we plante. Be bambae olgeta oli kambak, oli winim ol ples long kantri ya Fonisia, go kasem taon ya Jarefat long not. Mo ol man Jerusalem* we oli stap wok slef long taon ya Sadis, bambae oli kam holem ol taon long Juda long saed i go long saot."],[1,21,"Mo ol man ya we oli win long faet bambae oli go antap long hil ya Saeon,* nao bambae oli rulum kantri ya Edom, mo mi Hae God, bambae mi nomo mi King.”","Mo ol man ya we oli win long faet bambae oli go antap long hil ya Saeon,* nao bambae oli rulum kantri ya Edom, mo mi Hae God, bambae mi nomo mi King.”"]],"hbo-wlc":[[1,1,"חֲז֖וֹן עֹֽבַדְיָ֑ה כֹּֽה־אָמַר֩ אֲדֹנָ֨י יְהוִ֜ה לֶאֱד֗וֹם שְׁמוּעָ֨ה שָׁמַ֜עְנוּ מֵאֵ֤ת יְהוָה֙ וְצִיר֙ בַּגּוֹיִ֣ם שֻׁלָּ֔ח ק֛וּמוּ וְנָק֥וּמָה עָלֶיהָ לַמִּלְחָמָֽה׃","ẖàz֖wòn ʻòֽbadĕyá֑h kòֽ̇h-ʼámar֩ ʼàdòná֨y yĕhwi֜h leʼèd֗wòm şĕ̌mẇʻá֨h şá̌ma֜ʻĕnẇ méʼé֤ţ yĕhwáh֙ wĕẕiyr֙ bȧġwòyi֣m şǔlá̇֔ẖ q֛ẇmẇ wĕnáq֥ẇmáh ʻáleyhá lami̇lĕẖámáֽh׃"],[1,2,"הִנֵּ֥ה קָטֹ֛ן נְתַתִּ֖יךָ בַּגּוֹיִ֑ם בָּז֥וּי אַתָּ֖ה מְאֹֽד׃","hiné֥̇h qátò֛n nĕţaţi֖̇yká bȧġwòyi֑m bá̇z֥ẇy ʼaţá֖̇h mĕʼòֽd׃"],[1,3,"זְד֤וֹן לִבְּךָ֙ הִשִּׁיאֶ֔ךָ שֹׁכְנִ֥י בְחַגְוֵי־סֶּ֖לַע מְר֣וֹם שִׁבְתּ֑וֹ אֹמֵ֣ר בְּלִבּ֔וֹ מִ֥י יוֹרִדֵ֖נִי אָֽרֶץ׃","zĕd֤wòn libĕ̇ká֙ hişi̇̌yʼe֔ká şò̌kĕni֥y bĕẖagĕwéy-sė֖laʻ mĕr֣wòm şǐbĕţ֑̇wò ʼòmé֣r bĕ̇liḃ֔wò mi֥y ywòridé֖niy ʼáֽreẕ׃"],[1,4,"אִם־תַּגְבִּ֣יהַּ כַּנֶּ֔שֶׁר וְאִם־בֵּ֥ין כּֽוֹכָבִ֖ים שִׂ֣ים קִנֶּ֑ךָ מִשָּׁ֥ם אוֹרִֽידְךָ֖ נְאֻם־יְהוָֽה׃","ʼim-ţȧgĕbi֣̇yhȧ kȧnė֔şěr wĕʼim-bé֥̇yn kֽ̇wòkábi֖ym şî֣ym qinė֑ká mişá֥̇̌m ʼwòriֽydĕká֖ nĕʼum-yĕhwáֽh׃"],[1,5,"אִם־גַּנָּבִ֤ים בָּאֽוּ־לְךָ֙ אִם־שׁ֣וֹדְדֵי לַ֔יְלָה אֵ֣יךְ נִדְמֵ֔יתָה הֲל֥וֹא יִגְנְב֖וּ דַּיָּ֑ם אִם־בֹּֽצְרִים֙ בָּ֣אוּ לָ֔ךְ הֲל֖וֹא יַשְׁאִ֥ירוּ עֹלֵלֽוֹת׃","ʼim-gȧná̇bi֤ym bá̇ʼֽẇ-lĕká֙ ʼim-ş֣̌wòdĕdéy la֔yĕláh ʼé֣ykĕ nidĕmé֔yţáh hàl֥wòʼ yigĕnĕb֖ẇ dȧyá֑̇m ʼim-bòֽ̇ẕĕriym֙ bá֣̇ʼẇ lá֔kĕ hàl֖wòʼ yaşĕ̌ʼi֥yrẇ ʻòlélֽwòţ׃"],[1,6,"אֵ֚יךְ נֶחְפְּשׂ֣וּ עֵשָׂ֔ו נִבְע֖וּ מַצְפֻּנָֽיו׃","ʼé֚ykĕ neẖĕpĕ̇ş֣̂ẇ ʻéşá̂֔w nibĕʻ֖ẇ maẕĕpu̇náֽyw׃"],[1,7,"עַֽד־הַגְּב֣וּל שִׁלְּח֗וּךָ כֹּ֚ל אַנְשֵׁ֣י בְרִיתֶ֔ךָ הִשִּׁיא֛וּךָ יָכְל֥וּ לְךָ֖ אַנְשֵׁ֣י שְׁלֹמֶ֑ךָ לַחְמְךָ֗ יָשִׂ֤ימוּ מָזוֹר֙ תַּחְתֶּ֔יךָ אֵ֥ין תְּבוּנָ֖ה בּֽוֹ׃","ʻaֽd-hagĕ̇b֣ẇl şǐlĕ̇ẖ֗ẇká kò֚̇l ʼanĕşé֣̌y bĕriyţe֔ká hişi̇̌yʼ֛ẇká yákĕl֥ẇ lĕká֖ ʼanĕşé֣̌y şĕ̌lòme֑ká laẖĕmĕká֗ yáşî֤ymẇ mázwòr֙ ţȧẖĕţė֔yká ʼé֥yn ţĕ̇bẇná֖h ḃֽwò׃"],[1,8,"הֲל֛וֹא בַּיּ֥וֹם הַה֖וּא נְאֻם־יְהוָ֑ה וְהַאֲבַדְתִּ֤י חֲכָמִים֙ מֵֽאֱד֔וֹם וּתְבוּנָ֖ה מֵהַ֥ר עֵשָֽׂו׃","hàl֛wòʼ bȧẏ֥wòm hah֖ẇʼ nĕʼum-yĕhwá֑h wĕhaʼàbadĕţi֤̇y ẖàkámiym֙ méֽʼèd֔wòm ẇţĕbẇná֖h méha֥r ʻéşáֽ̂w׃"],[1,9,"וְחַתּ֥וּ גִבּוֹרֶ֖יךָ תֵּימָ֑ן לְמַ֧עַן יִכָּֽרֶת־אִ֛ישׁ מֵהַ֥ר עֵשָׂ֖ו מִקָּֽטֶל׃","wĕẖaţ֥̇ẇ giḃwòre֖yká ţé̇ymá֑n lĕma֧ʻan yikáֽ̇reţ-ʼi֛yş̌ méha֥r ʻéşá֖̂w miqáֽ̇tel׃"],[1,10,"מֵחֲמַ֛ס אָחִ֥יךָ יַעֲקֹ֖ב תְּכַסְּךָ֣ בוּשָׁ֑ה וְנִכְרַ֖תָּ לְעוֹלָֽם׃","méẖàma֛s ʼáẖi֥yká yaʻàqò֖b ţĕ̇kasĕ̇ká֣ bẇşá֑̌h wĕnikĕra֖ţá̇ lĕʻwòláֽm׃"],[1,11,"בְּיוֹם֙ עֲמָֽדְךָ֣ מִנֶּ֔גֶד בְּי֛וֹם שְׁב֥וֹת זָרִ֖ים חֵיל֑וֹ וְנָכְרִ֞ים בָּ֣אוּ שערו וְעַל־יְרוּשָׁלִַ֙ם֙ יַדּ֣וּ גוֹרָ֔ל גַּם־אַתָּ֖ה כְּאַחַ֥ד מֵהֶֽם׃","bĕ̇ywòm֙ ʻàmáֽdĕká֣ minė֔ged bĕ̇y֛wòm şĕ̌b֥wòţ zári֖ym ẖéyl֑wò wĕnákĕri֞ym bá֣̇ʼẇ şʻrw wĕʻal-yĕrẇşá̌lia֙m֙ yaḋ֣ẇ gwòrá֔l gȧm-ʼaţá֖̇h kĕ̇ʼaẖa֥d méheֽm׃"],[1,12,"וְאַל־תֵּ֤רֶא בְיוֹם־אָחִ֙יךָ֙ בְּי֣וֹם נָכְר֔וֹ וְאַל־תִּשְׂמַ֥ח לִבְנֵֽי־יְהוּדָ֖ה בְּי֣וֹם אָבְדָ֑ם וְאַל־תַּגְדֵּ֥ל פִּ֖יךָ בְּי֥וֹם צָרָֽה׃","wĕʼal-ţé֤̇reʼ bĕywòm-ʼáẖi֙yká֙ bĕ̇y֣wòm nákĕr֔wò wĕʼal-ţi̇şĕ̂ma֥ẖ libĕnéֽy-yĕhẇdá֖h bĕ̇y֣wòm ʼábĕdá֑m wĕʼal-ţȧgĕdé֥̇l pi֖̇yká bĕ̇y֥wòm ẕáráֽh׃"],[1,13,"אַל־תָּב֤וֹא בְשַֽׁעַר־עַמִּי֙ בְּי֣וֹם אֵידָ֔ם אַל־תֵּ֧רֶא גַם־אַתָּ֛ה בְּרָעָת֖וֹ בְּי֣וֹם אֵיד֑וֹ וְאַל־תִּשְׁלַ֥חְנָה בְחֵיל֖וֹ בְּי֥וֹם אֵידֽוֹ׃","ʼal-ţá̇b֤wòʼ bĕşǎֽʻar-ʻami̇y֙ bĕ̇y֣wòm ʼéydá֔m ʼal-ţé֧̇reʼ gam-ʼaţá֛̇h bĕ̇ráʻáţ֖wò bĕ̇y֣wòm ʼéyd֑wò wĕʼal-ţi̇şĕ̌la֥ẖĕnáh bĕẖéyl֖wò bĕ̇y֥wòm ʼéydֽwò׃"],[1,14,"וְאַֽל־תַּעֲמֹד֙ עַל־הַפֶּ֔רֶק לְהַכְרִ֖ית אֶת־פְּלִיטָ֑יו וְאַל־תַּסְגֵּ֥ר שְׂרִידָ֖יו בְּי֥וֹם צָרָֽה׃","wĕʼaֽl-ţȧʻàmòd֙ ʻal-hapė֔req lĕhakĕri֖yţ ʼeţ-pĕ̇liytá֑yw wĕʼal-ţȧsĕgé֥̇r şĕ̂riydá֖yw bĕ̇y֥wòm ẕáráֽh׃"],[1,15,"כִּֽי־קָר֥וֹב יוֹם־יְהוָ֖ה עַל־כָּל־הַגּוֹיִ֑ם כַּאֲשֶׁ֤ר עָשִׂ֙יתָ֙ יֵעָ֣שֶׂה לָּ֔ךְ גְּמֻלְךָ֖ יָשׁ֥וּב בְּרֹאשֶֽׁךָ׃","kiֽ̇y-qár֥wòb ywòm-yĕhwá֖h ʻal-ká̇l-haġwòyi֑m kȧʼàşě֤r ʻáşî֙yţá֙ yéʻá֣şêh lá̇֔kĕ gĕ̇mulĕká֖ yáş֥̌ẇb bĕ̇ròʼşěֽká׃"],[1,16,"כִּ֗י כַּֽאֲשֶׁ֤ר שְׁתִיתֶם֙ עַל־הַ֣ר קָדְשִׁ֔י יִשְׁתּ֥וּ כָֽל־הַגּוֹיִ֖ם תָּמִ֑יד וְשָׁת֣וּ וְלָע֔וּ וְהָי֖וּ כְּל֥וֹא הָיֽוּ׃","ki̇֗y kȧֽʼàşě֤r şĕ̌ţiyţem֙ ʻal-ha֣r qádĕşǐ֔y yişĕ̌ţ֥̇ẇ káֽl-haġwòyi֖m ţá̇mi֑yd wĕşá̌ţ֣ẇ wĕláʻ֔ẇ wĕháy֖ẇ kĕ̇l֥wòʼ háyֽẇ׃"],[1,17,"וּבְהַ֥ר צִיּ֛וֹן תִּהְיֶ֥ה פְלֵיטָ֖ה וְהָ֣יָה קֹ֑דֶשׁ וְיָֽרְשׁוּ֙ בֵּ֣ית יַֽעֲקֹ֔ב אֵ֖ת מוֹרָֽשֵׁיהֶם׃","ẇbĕha֥r ẕiẏ֛wòn ţi̇hĕye֥h pĕléytá֖h wĕhá֣yáh qò֑deş̌ wĕyáֽrĕş̌ẇ֙ bé֣̇yţ yaֽʻàqò֔b ʼé֖ţ mwòráֽşé̌yhem׃"],[1,18,"וְהָיָה֩ בֵית־יַעֲקֹ֨ב אֵ֜שׁ וּבֵ֧ית יוֹסֵ֣ף לֶהָבָ֗ה וּבֵ֤ית עֵשָׂו֙ לְקַ֔שׁ וְדָלְק֥וּ בָהֶ֖ם וַאֲכָל֑וּם וְלֹֽא־יִֽהְיֶ֤ה שָׂרִיד֙ לְבֵ֣ית עֵשָׂ֔ו כִּ֥י יְהוָ֖ה דִּבֵּֽר׃","wĕháyáh֩ béyţ-yaʻàqò֨b ʼé֜ş̌ ẇbé֧yţ ywòsé֣p lehábá֗h ẇbé֤yţ ʻéşá̂w֙ lĕqa֔ş̌ wĕdálĕq֥ẇ báhe֖m waʼàkál֑ẇm wĕlòֽʼ-yiֽhĕye֤h şá̂riyd֙ lĕbé֣yţ ʻéşá̂֔w ki֥̇y yĕhwá֖h di̇béֽ̇r׃"],[1,19,"וְיָרְשׁ֨וּ הַנֶּ֜גֶב אֶת־הַ֣ר עֵשָׂ֗ו וְהַשְּׁפֵלָה֙ אֶת־פְּלִשְׁתִּ֔ים וְיָרְשׁוּ֙ אֶת־שְׂדֵ֣ה אֶפְרַ֔יִם וְאֵ֖ת שְׂדֵ֣ה שֹׁמְר֑וֹן וּבִנְיָמִ֖ן אֶת־הַגִּלְעָֽד׃","wĕyárĕş̌֨ẇ hanė֜geb ʼeţ-ha֣r ʻéşá̂֗w wĕhaşĕ̇̌péláh֙ ʼeţ-pĕ̇lişĕ̌ţi̇֔ym wĕyárĕş̌ẇ֙ ʼeţ-şĕ̂dé֣h ʼepĕra֔yim wĕʼé֖ţ şĕ̂dé֣h şò̌mĕr֑wòn ẇbinĕyámi֖n ʼeţ-hagi̇lĕʻáֽd׃"],[1,20,"וְגָלֻ֣ת הַֽחֵל־הַ֠זֶּה לִבְנֵ֨י יִשְׂרָאֵ֤ל אֲשֶֽׁר־כְּנַעֲנִים֙ עַד־צָ֣רְפַ֔ת וְגָלֻ֥ת יְרוּשָׁלִַ֖ם אֲשֶׁ֣ר בִּסְפָרַ֑ד יִֽרְשׁ֕וּ אֵ֖ת עָרֵ֥י הַנֶּֽגֶב׃","wĕgálu֣ţ haֽẖél-ha֠zėh libĕné֨y yişĕ̂ráʼé֤l ʼàşěֽr-kĕ̇naʻàniym֙ ʻad-ẕá֣rĕpa֔ţ wĕgálu֥ţ yĕrẇşá̌lia֖m ʼàşě֣r bi̇sĕpára֑d yiֽrĕş̌֕ẇ ʼé֖ţ ʻáré֥y hanėֽgeb׃"],[1,21,"וְעָל֤וּ מֽוֹשִׁעִים֙ בְּהַ֣ר צִיּ֔וֹן לִשְׁפֹּ֖ט אֶת־הַ֣ר עֵשָׂ֑ו וְהָיְתָ֥ה לַֽיהוָ֖ה הַמְּלוּכָֽה׃","wĕʻál֤ẇ mֽwòşǐʻiym֙ bĕ̇ha֣r ẕiẏ֔wòn lişĕ̌pò֖̇t ʼeţ-ha֣r ʻéşá֑̂w wĕháyĕţá֥h laֽyhwá֖h hamĕ̇lẇkáֽh׃"]],"fra-giguet-lxx":[[1,1,"Vision d’Abdias. Voici ce que le Seigneur Dieu dit à l’Idumée: J’ai entendu la parole du Seigneur, et il a envoyé un message aux gentils, disant: Levez-vous, et allons combattre Édom!","Vision d’Abdias. Voici ce que le Seigneur Dieu dit à l’Idumée: J’ai entendu la parole du Seigneur, et il a envoyé un message aux gentils, disant: Levez-vous, et allons combattre Édom!"],[1,2,"Voilà que je t’ai réduit à un petit nombre parmi les peuples; et tu es maintenant sans honneur.","Voilà que je t’ai réduit à un petit nombre parmi les peuples; et tu es maintenant sans honneur."],[1,3,"L’orgueil de ton cœur t’avait enivré, toi qui résides dans les trous des rochers; élevant ta demeure sur les hauts lieux, tu disais: Qui me fera descendre à terre?","L’orgueil de ton cœur t’avait enivré, toi qui résides dans les trous des rochers; élevant ta demeure sur les hauts lieux, tu disais: Qui me fera descendre à terre?"],[1,4,"Quand même tu te serais élevé autant que l’aigle, quand tu aurais placé ton nid au milieu des étoiles, je t’en précipiterais, dit le Seigneur.","Quand même tu te serais élevé autant que l’aigle, quand tu aurais placé ton nid au milieu des étoiles, je t’en précipiterais, dit le Seigneur."],[1,5,"Si des larrons ou des voleurs de nuit étaient entrés chez toi, à quel point t’auraient-ils abattu? N’auraient-ils pas seulement enlevé ce qui leur eût convenu? Et si des vendangeurs étaient entrés en ta vigne, ne t’auraient-ils pas laissé au moins un grappillon?","Si des larrons ou des voleurs de nuit étaient entrés chez toi, à quel point t’auraient-ils abattu? N’auraient-ils pas seulement enlevé ce qui leur eût convenu? Et si des vendangeurs étaient entrés en ta vigne, ne t’auraient-ils pas laissé au moins un grappillon?"],[1,6,"Comment Ésau a-t-il été fouillé, et comment lui a-t-on pris ce qu’il cachait?","Comment Ésau a-t-il été fouillé, et comment lui a-t-on pris ce qu’il cachait?"],[1,7,"Ils t’ont chassé jusqu’à tes extrêmes limites; tous tes alliés sont devenus tes ennemis; des hommes pacifiques avec qui tu vivais en paix ont prévalu contre toi; ils ont placé des piéges sous tes pas; mais Édom est sans intelligence.","Ils t’ont chassé jusqu’à tes extrêmes limites; tous tes alliés sont devenus tes ennemis; des hommes pacifiques avec qui tu vivais en paix ont prévalu contre toi; ils ont placé des piéges sous tes pas; mais Édom est sans intelligence."],[1,8,"Ce jour-là, dit le Seigneur, je détruirai les sages de l’Idumée, et je bannirai l’intelligence des montagnes d’Ésau.","Ce jour-là, dit le Seigneur, je détruirai les sages de l’Idumée, et je bannirai l’intelligence des montagnes d’Ésau."],[1,9,"Et tes guerriers de Théman trembleront de peur, afin que tout homme soit exterminé sur le mont d’Ésau.","Et tes guerriers de Théman trembleront de peur, afin que tout homme soit exterminé sur le mont d’Ésau."],[1,10,"A cause de tes meurtres, et de tes péchés contre ton frère Jacob, tu seras couvert de confusion, et tu seras effacé pour jamais.","A cause de tes meurtres, et de tes péchés contre ton frère Jacob, tu seras couvert de confusion, et tu seras effacé pour jamais."],[1,11,"Du jour où tu t’es levé contre lui, quand des peuples étrangers emmenèrent son armée captive, quand ils franchirent ses portes, et tirèrent au sort les richesses de Jérusalem, dès lors tu fus comme l’un d’eux.","Du jour où tu t’es levé contre lui, quand des peuples étrangers emmenèrent son armée captive, quand ils franchirent ses portes, et tirèrent au sort les richesses de Jérusalem, dès lors tu fus comme l’un d’eux."],[1,12,"Ne méprise pas la chute de ton frère au jour des étrangers: ne te raille pas des fils de Juda au jour de leur ruine; ne te gonfle pas d’orgueil au jour de leur angoisse.","Ne méprise pas la chute de ton frère au jour des étrangers: ne te raille pas des fils de Juda au jour de leur ruine; ne te gonfle pas d’orgueil au jour de leur angoisse."],[1,13,"N’entre point par les portes de mon peuple au jour de ses souffrances; ne surveille pas sa Synagogue au jour de sa destruction; n’attaque pas son armée le jour où ils périront.","N’entre point par les portes de mon peuple au jour de ses souffrances; ne surveille pas sa Synagogue au jour de sa destruction; n’attaque pas son armée le jour où ils périront."],[1,14,"Ne te tiens pas sur leur chemin pour massacrer ceux qui se sont échappés; n’enferme pas leurs fuyards au jour de la désolation.","Ne te tiens pas sur leur chemin pour massacrer ceux qui se sont échappés; n’enferme pas leurs fuyards au jour de la désolation."],[1,15,"Car le jour du Seigneur est proche pour toutes les nations; comme tu as fait à autrui, il te sera fait à toimême; ta rétribution retombera sur ta tête.","Car le jour du Seigneur est proche pour toutes les nations; comme tu as fait à autrui, il te sera fait à toimême; ta rétribution retombera sur ta tête."],[1,16,"Car de même que tu auras bu sur ma montagne sainte, ainsi toutes les nations boiront le vin de ma colère; elles boiront, et elles tomberont, et elles seront comme ceux qui ne sont plus.","Car de même que tu auras bu sur ma montagne sainte, ainsi toutes les nations boiront le vin de ma colère; elles boiront, et elles tomberont, et elles seront comme ceux qui ne sont plus."],[1,17,"Et le salut sera en la montagne de Sion, et elle sera sainte, et la maison de Jacob possèdera ceux qui l’auront possédée.","Et le salut sera en la montagne de Sion, et elle sera sainte, et la maison de Jacob possèdera ceux qui l’auront possédée."],[1,18,"Et la maison de Jacob sera un feu, et la maison de Joseph une flamme; et la maison d’Ésau sera comme un chaume; et ceux d’Israël porteront chez elle l’incendie, et ils la dévoreront; et il n’y aura plus un champ qui porte du blé, en la maison d’Ésau; car le Seigneur a parlé.","Et la maison de Jacob sera un feu, et la maison de Joseph une flamme; et la maison d’Ésau sera comme un chaume; et ceux d’Israël porteront chez elle l’incendie, et ils la dévoreront; et il n’y aura plus un champ qui porte du blé, en la maison d’Ésau; car le Seigneur a parlé."],[1,19,"Et ceux de Nageb auront pour héritage la montagne d’Ésau, et ceux de Sephéla le pays des Philistins; et ils auront aussi pour héritage la montagne d’Éphraïm, et la plaine de Samarie, et Benjamin et Galaad.","Et ceux de Nageb auront pour héritage la montagne d’Ésau, et ceux de Sephéla le pays des Philistins; et ils auront aussi pour héritage la montagne d’Éphraïm, et la plaine de Samarie, et Benjamin et Galaad."],[1,20,"Et voici le domaine des fils d’lsraël qui reviendront de la captivité: la terre des Chananéens jusqu’à Sarepta; ceux de Jérusalem possèderont jusqu’à Éphratha; ils auront les cités de Nageb.","Et voici le domaine des fils d’lsraël qui reviendront de la captivité: la terre des Chananéens jusqu’à Sarepta; ceux de Jérusalem possèderont jusqu’à Éphratha; ils auront les cités de Nageb."],[1,21,"Et ceux de la montagne de Sion qui auront été sauvés monteront pour punir la montagne d’Ésau; et alors arrivera le règne du Seigneur.","Et ceux de la montagne de Sion qui auront été sauvés monteront pour punir la montagne d’Ésau; et alors arrivera le règne du Seigneur."]],"ell-vamvas1850":[[1,1,"Όρασις Αβδιού. Ούτω λέγει Κύριος ο Θεός περί του Εδώμ· Ηκούσαμεν αγγελίαν παρά Κυρίου και μηνυτής απεστάλη προς τα έθνη, Εγέρθητε και ας εγερθώμεν εναντίον αυτού εις πόλεμον.","Órasis Abdioú. Oútō légei Kýrios o Theós perí tou Edṓm: Ēkoúsamen angelían pará Kyríou kai mēnytḗs apestálē pros ta éthnē, Egérthēte kai as egerthṓmen enantíon autoú eis pólemon."],[1,2,"Ιδού, σε κατέστησα μικρόν μεταξύ των εθνών· είσαι καταπεφρονημένος σφόδρα.","Idoú, se katéstēsa mikrón metaxý tōn ethnṓn: eísai katapephronēménos sphódra."],[1,3,"Η υπερηφανία της καρδίας σου ηπάτησε σε τον κατοικούντα εν τοις κοιλώμασι των κρημνών, του οποίου η κατοικία είναι υψηλή, όστις λέγει εν τη καρδία αυτού, Τις θέλει με καταβιβάσει εις την γην;","Ē yperēphanía tēs kardías sou ēpátēse se ton katoikoúnta en tois koilṓmasi tōn krēmnṓn, tou opoíou ē katoikía eínai ypsēlḗ, óstis légei en tē kardía autoú, Tis thélei me katabibásei eis tēn gēn?"],[1,4,"Εάν μετεωρισθής ως αετός και εάν θέσης την φωλεάν σου αναμέσον των άστρων, και εκείθεν θέλω σε καταβιβάσει, λέγει Κύριος.","Eán meteōristhḗs ōs aetós kai eán thésēs tēn phōleán sou anaméson tōn ástrōn, kai ekeíthen thélō se katabibásei, légei Kýrios."],[1,5,"Εάν κλέπται ήρχοντο προς σε, εάν λησταί διά νυκτός -πως εξηλείφθης- δεν ήθελον αρπάσει το αρκούν εις αυτούς; εάν τρυγηταί ήρχοντο προς σε, δεν ήθελον αφήσει επιφυλλίδας;","Eán kléptai ḗrchonto pros se, eán lēstaí diá nyktós -pōs exēleíphthēs- den ḗthelon arpásei to arkoún eis autoús? eán trygētaí ḗrchonto pros se, den ḗthelon aphḗsei epiphyllídas?"],[1,6,"Πως εξηρευνήθη ο Ησαύ· απεκαλύφθησαν οι κρυψώνες αυτού.","Pōs exēreunḗthē o Ēsaú: apekalýphthēsan oi krypsṓnes autoú."],[1,7,"Πάντες οι άνδρες της συμμαχίας σου σε συνώδευσαν έως του ορίου σου· οι άνθρωποι, οίτινες ήσαν εν ειρήνη μετά σου, σε ηπάτησαν και υπερίσχυσαν εναντίον σου· οι τρώγοντες τον άρτον σου έβαλον ενέδραν υποκάτω σου· δεν υπάρχει σύνεσις εν αυτώ.","Pántes oi ándres tēs symmachías sou se synṓdeusan éōs tou oríou sou: oi ánthrōpoi, oítines ḗsan en eirḗnē metá sou, se ēpátēsan kai yperíschysan enantíon sou: oi trṓgontes ton árton sou ébalon enédran ypokátō sou: den ypárchei sýnesis en autṓ."],[1,8,"Εν τη ημέρα εκείνη, λέγει Κύριος, δεν θέλω απολέσει και τους σοφούς από του Εδώμ και την σύνεσιν από του όρους του Ησαύ;","En tē ēméra ekeínē, légei Kýrios, den thélō apolései kai tous sophoús apó tou Edṓm kai tēn sýnesin apó tou órous tou Ēsaú?"],[1,9,"Και οι μαχηταί σου, Θαιμάν, θέλουσι πτοηθή, διά να εκκοπή εν σφαγή πας άνθρωπος εκ του όρους του Ησαύ.","Kai oi machētaí sou, Thaimán, thélousi ptoēthḗ, diá na ekkopḗ en sphagḗ pas ánthrōpos ek tou órous tou Ēsaú."],[1,10,"Διά την αδικίαν την προς τον αδελφόν σου Ιακώβ θέλει σε καλύψει αισχύνη και θέλεις εκκοπή διαπαντός.","Diá tēn adikían tēn pros ton adelphón sou Iakṓb thélei se kalýpsei aischýnē kai théleis ekkopḗ diapantós."],[1,11,"Εν τη ημέρα καθ' ην ίστασο απέναντι, τη ημέρα καθ' ην οι αλλογενείς έφεραν εις αιχμαλωσίαν το στράτευμα αυτού και οι αλλότριοι εισήλθον εις τας πύλας αυτού και έβαλον κλήρους επί την Ιερουσαλήμ, έσο και συ ως εις αυτών.","En tē ēméra kath' ēn ístaso apénanti, tē ēméra kath' ēn oi allogeneís épheran eis aichmalōsían to stráteuma autoú kai oi allótrioi eisḗlthon eis tas pýlas autoú kai ébalon klḗrous epí tēn Ierousalḗm, éso kai sy ōs eis autṓn."],[1,12,"Δεν έπρεπεν όμως να επιβλέπης εις την ημέραν του αδελφού σου, εις την ημέραν της αποξενώσεως αυτού, ουδέ να επιχαίρης κατά των υιών του Ιούδα εν τη ημέρα του αφανισμού αυτών, ουδέ να μεγαλορρημονής εν τη ημέρα της θλίψεως αυτών.","Den éprepen ómōs na epiblépēs eis tēn ēméran tou adelphoú sou, eis tēn ēméran tēs apoxenṓseōs autoú, oudé na epichaírēs katá tōn yiṓn tou Ioúda en tē ēméra tou aphanismoú autṓn, oudé na megalorrēmonḗs en tē ēméra tēs thlípseōs autṓn."],[1,13,"Δεν έπρεπε να εισέλθης εις την πύλην του λαού μου εν τη ημέρα της συμφοράς αυτών, ουδέ να θεωρής και συ την θλίψιν αυτών εν τη ημέρα της συμφοράς αυτών, ουδέ να επιβάλης χείρα επί την περιουσίαν αυτών εν τη ημέρα της συμφοράς αυτών,","Den éprepe na eisélthēs eis tēn pýlēn tou laoú mou en tē ēméra tēs symphorás autṓn, oudé na theōrḗs kai sy tēn thlípsin autṓn en tē ēméra tēs symphorás autṓn, oudé na epibálēs cheíra epí tēn periousían autṓn en tē ēméra tēs symphorás autṓn,"],[1,14,"ουδέ έπρεπε να σταθής επί τας διεξόδους, διά να αποκλείης τους διασωζομένους αυτού ουδέ να παραδώσης τους υπολοίπους αυτού εν τη ημέρα της θλίψεως αυτών","oudé éprepe na stathḗs epí tas diexódous, diá na apokleíēs tous diasōzoménous autoú oudé na paradṓsēs tous ypoloípous autoú en tē ēméra tēs thlípseōs autṓn"],[1,15,"διότι εγγύς είναι η ημέρα του Κυρίου επί πάντα τα έθνη· καθώς έκαμες θέλει γείνει εις σέ· η ανταπόδοσίς σου θέλει στρέψει επί την κεφαλήν σου.","dióti engýs eínai ē ēméra tou Kyríou epí pánta ta éthnē: kathṓs ékames thélei geínei eis sé: ē antapódosís sou thélei strépsei epí tēn kephalḗn sou."],[1,16,"Διότι καθώς σεις επίετε επί το όρος το άγιόν μου, ούτω θέλουσι πίνει διαπαντός πάντα τα έθνη· ναι, θέλουσι πίνει και θέλουσιν εκροφεί και θέλουσιν είσθαι ως οι μη υπάρχοντες","Dióti kathṓs seis epíete epí to óros to ágión mou, oútō thélousi pínei diapantós pánta ta éthnē: nai, thélousi pínei kai thélousin ekropheí kai thélousin eísthai ōs oi mē ypárchontes"],[1,17,"Επί δε του όρους Σιών θέλει είσθαι σωτηρία και θέλει είσθαι άγιον· και ο οίκος Ιακώβ θέλει κατακληρονομήσει τας κληρονομίας αυτών·","Epí de tou órous Siṓn thélei eísthai sōtēría kai thélei eísthai ágion: kai o oíkos Iakṓb thélei kataklēronomḗsei tas klēronomías autṓn:"],[1,18,"και ο οίκος Ιακώβ θέλει είσθαι πυρ και ο οίκος Ιωσήφ φλόξ, ο δε οίκος Ησαύ ως καλάμη· και θέλουσιν εξαφθή κατ' αυτών και καταφάγει αυτούς· και δεν θέλει είσθαι υπόλοιπον του οίκου Ησαύ· διότι Κύριος ελάλησε.","kai o oíkos Iakṓb thélei eísthai pyr kai o oíkos Iōsḗph phlóx, o de oíkos Ēsaú ōs kalámē: kai thélousin exaphthḗ kat' autṓn kai kataphágei autoús: kai den thélei eísthai ypóloipon tou oíkou Ēsaú: dióti Kýrios elálēse."],[1,19,"Και οι της μεσημβρίας θέλουσι κατακληρονομήσει το όρος του Ησαύ και οι της πεδινής τους Φιλισταίους· και θέλουσι κατακληρονομήσει τους αγρούς του Εφραΐμ και τους αγρούς της Σαμαρείας, ο δε Βενιαμίν την Γαλαάδ,","Kai oi tēs mesēmbrías thélousi kataklēronomḗsei to óros tou Ēsaú kai oi tēs pedinḗs tous Philistaíous: kai thélousi kataklēronomḗsei tous agroús tou Ephraḯm kai tous agroús tēs Samareías, o de Beniamín tēn Galaád,"],[1,20,"και το αιχμαλωτισθέν τούτο στράτευμα των υιών Ισραήλ την γην εκείνην των Χαναναίων έως Σαρεπτά, και οι αιχμαλωτισθέντες της Ιερουσαλήμ, οι εν Σεφαράδ, θέλουσι κατακληρονομήσει τας πόλεις του νότου·","kai to aichmalōtisthén toúto stráteuma tōn yiṓn Israḗl tēn gēn ekeínēn tōn Chananaíōn éōs Sareptá, kai oi aichmalōtisthéntes tēs Ierousalḗm, oi en Sepharád, thélousi kataklēronomḗsei tas póleis tou nótou:"],[1,21,"και θέλουσιν αναβή σωτήρες εις το όρος Σιών, διά να κρίνωσι το όρος του Ησαύ· και του Κυρίου θέλει είσθαι η βασιλεία.","kai thélousin anabḗ sōtḗres eis to óros Siṓn, diá na krínōsi to óros tou Ēsaú: kai tou Kyríou thélei eísthai ē basileía."]],"grc-swete":[[1,0,"ΡΑΣΙΣ Ὀβδειού.","RASIS Obdeioú."],[1,1,"Τάδε λέγει Κύριος ὁ θεὸς τῇ Ἰδουμαίᾳ Ἀκοὴν ἤκουσα παρὰ Κυρίου, καὶ περιοχὴν εἰς τὰ ἔθνη ἐξαπέστειλεν Ἀνάστητε καὶ ἐξαναστῶμεν ἐπʼ αὐτὴν εἰς πόλεμον.","Táde légei Kýrios ho theòs tē̂i Idoumaíāi Akoḕn ḗkousa parà Kyríou, kaì periochḕn eis tà éthnē exapésteilen Anástēte kaì exanastō̂men epʼ autḕn eis pólemon."],[1,2,"ἰδοὺ ὀλιγοστὸν δέδωκά σε ἐν τοῖς ἔθνεσιν, ἠτιμωμένος σὺ εἶ σφόδρα·","idoù oligostòn dédōká se en toîs éthnesin, ētimōménos sỳ eî sphódra:"],[1,3,"ὑπερηφανία τῆς καρδίας σου ἐπῆρέν σε κατασκηνοῦντα ἐν ταῖς ὀπαῖς τῶν πετρῶν· ὑψῶν κατοικίαν αὐτοῦ, λέγων ἐν καρδίᾳ αὐτοῦ Τίς με κατάξει ἐπὶ τὴν γῆν ;","hyperēphanía tē̂s kardías sou epē̂rén se kataskēnoûnta en taîs opaîs tō̂n petrō̂n: hypsō̂n katoikían autoû, légōn en kardíāi autoû Tís me katáxei epì tḕn gē̂n ?"],[1,4,"ἐὰν μετεωρισθῇς ὡς ἀετός, καὶ ἐὰν ἀνὰ μέσον τῶν ἄστρων θῇς νοσσιάν σου, ἐκεῖθεν κατάξω σε, λέγει Κύριος.","eàn meteōristhē̂is hōs aetós, kaì eàn anà méson tō̂n ástrōn thē̂is nossián sou, ekeîthen katáxō se, légei Kýrios."],[1,5,"εἰ κλέπται εἰσῆλθον πρὸς σὲ ἢ λῃσταὶ νυκτός, ποῦ ἂν ἀπερρίφης; οὐκ ἂν ἔκλεψαν τὰ ἱκανὰ ἑαυτοῖς; καὶ εἰ τρυγηταὶ εἰσῆλθον πρὸς σέ, οὐκ ἂν ὑπελίποντο ἐπιφυλλίδας;","ei kléptai eisē̂lthon pròs sè ḕ lēistaì nyktós, poû àn aperríphēs? ouk àn éklepsan tà hikanà heautoîs? kaì ei trygētaì eisē̂lthon pròs sé, ouk àn hypelíponto epiphyllídas?"],[1,6,"πῶς ἐξηρευνήθη Ἠσοὺ καὶ κατελήμφθη αὐτοῦ τὰ κεκριυμμένα.","pō̂s exēreunḗthē Ēsoù kaì katelḗmphthē autoû tà kekriumména."],[1,7,"ἕως τῶν ὁρίων ἐξαπέστειλάν σε· πάντες οἱ ἄνδρες τῆς διαθήκης σου ἀντέστησάν σοι, ἡδυνάσθησαν πρὸς σὲ ἄνδρες εἰρηνικοί σου, ἔθηκαν ἔνεδρα ὑποκάτω σου, οὐκ ἔστιν σύνεσις αὐτοῖς.","héōs tō̂n horíōn exapésteilán se: pántes hoi ándres tē̂s diathḗkēs sou antéstēsán soi, hēdynásthēsan pròs sè ándres eirēnikoí sou, éthēkan énedra hypokátō sou, ouk éstin sýnesis autoîs."],[1,8,"ἐν ἐκείνῃ τῇ ἡμέρᾳ, λέγει Κύριος, ἀπολῶ σοφοὺς ἐκ τῆς Ἰδουμαίας καὶ σύνεσιν ἐξ ὄρους Ἠσού·","en ekeínēi tē̂i hēmérāi, légei Kýrios, apolō̂ sophoùs ek tē̂s Idoumaías kaì sýnesin ex órous Ēsoú:"],[1,9,"καὶ πτοηθήσονται οἱ μαχηταί σου οἱ ἐκ Θαιμάν, ὅπαως ἐξαρθῇ ἄνθρωπος ἐξ ὄρους Ἠσαύ·","kaì ptoēthḗsontai hoi machētaí sou hoi ek Thaimán, hópaōs exarthē̂i ánthrōpos ex órous Ēsaú:"],[1,10,"διὰ τὴν σφαγὴν καὶ τὴν ἀσέβειαν ἀδελφοῦ σου Ἰακὼβ καλύψει σε αἰσχύνη, καὶ ἐξαρθήσῃ εἰς τὸν αἰῶνα.","dià tḕn sphagḕn kaì tḕn asébeian adelphoû sou Iakṑb kalýpsei se aischýnē, kaì exarthḗsēi eis tòn aiō̂na."],[1,11,"Ἀφʼ ἧς ἡμέρας ἀντέστης ἐξ ἐναντίας ἐν ἡμέραις αἰχμαλωτευόντων ἀλλογενῶν δύναμιν αὐτοῦ, καὶ ἀλλότριοι εἰσῆλθον εἰς πύλας αὐτοῦ καὶ ἐπὶ Ἰερουσαλὴμ ἔβαλον κλήρους, καὶ σὺ ἧς ὡς εἷς ἐξ αὐτῶν.","Aphʼ hē̂s hēméras antéstēs ex enantías en hēmérais aichmalōteuóntōn allogenō̂n dýnamin autoû, kaì allótrioi eisē̂lthon eis pýlas autoû kaì epì Ierousalḕm ébalon klḗrous, kaì sỳ hē̂s hōs heîs ex autō̂n."],[1,12,"καὶ μὴ ἐπίδῃς ἡμέραν ἀδελφοῦ σου ἐν ἡμέρᾳ ἀλλοτρίων, καὶ μὴ ἐπιχαρῆς ἐπὶ τοὺς υἱοὺς Ἰούδα ἐν ἡμέρᾳ ἀπωλίας αὐτῶν, καὶ μὴ μεγαλορημονῆς ἐν ἡμέρᾳ θλίψεως·","kaì mḕ epídēis hēméran adelphoû sou en hēmérāi allotríōn, kaì mḕ epicharē̂s epì toùs hyioùs Ioúda en hēmérāi apōlías autō̂n, kaì mḕ megalorēmonē̂s en hēmérāi thlípseōs:"],[1,13,"μηδὲ εἰσέλθῃς εἰς πύλας λαῶν ἐν ἡμέρᾳ πόνων αὐτῶν, μηδέ ἐπίδῃς καὶ σὺ τὴν συναγωγὴν αὐτάων ἐν ἡμέρᾳ ὀλέθρου αὐτῶν, μηδἐ συνεπιθῇ ἐπὶ τὴν δύναμιν αὐτῶν ἐν ἡμέρᾳ ἀπωλίας αὐτῶν·","mēdè eisélthēis eis pýlas laō̂n en hēmérāi pónōn autō̂n, mēdé epídēis kaì sỳ tḕn synagōgḕn autáōn en hēmérāi oléthrou autō̂n, mēde synepithē̂i epì tḕn dýnamin autō̂n en hēmérāi apōlías autō̂n:"],[1,14,"μηδὲ ἐπιστῆς ἐπὶ τὰς διεκβολὰς αὐτοῦ ἐξολεθρεῦσαι τοὺς ἀνασωζομένους αὐτοῦ, μηδέ συγκλείσῃς τοὺς φεύγοντας αὐτοῦ ἐν ἡμέρᾳ θλίψεως.","mēdè epistē̂s epì tàs diekbolàs autoû exolethreûsai toùs anasōzoménous autoû, mēdé synkleísēis toùs pheúgontas autoû en hēmérāi thlípseōs."],[1,15,"διότι ἐγγὺς ἡμέρα Κυρίου ἐπὶ πάντα τὰ ἔθνη· ὃν τρόπον ἐποίησας, οὕτως ἔσται σοι τὸ ἀνταπόδομά σου ἀνταποδοθήσεται εἰς κεφαλήν σου·","dióti engỳs hēméra Kyríou epì pánta tà éthnē: hòn trópon epoíēsas, hoútōs éstai soi tò antapódomá sou antapodothḗsetai eis kephalḗn sou:"],[1,16,"διότι ὃν τρόπον ἔπιες ἐπὶ τὸ ὄρος τὸ ἅγιόν μου, πίονται καὶ καταβήσονται, καὶ ἔσονται καθὼς οὐχ ὑπάρχοντες.","dióti hòn trópon épies epì tò óros tò hágión mou, píontai kaì katabḗsontai, kaì ésontai kathṑs ouch hypárchontes."],[1,17,"Ἐν δὲ τῷ ὄρει Σειὼν ἔσται σωτηρία, καὶ ἔσται ἅγιονʼ καὶ κατακληρονομήσουσιν ὁ οἵκος Ἰακὼβ τοὺς κατακληρονομήσαντας αὐτούς.","En dè tō̂i órei Seiṑn éstai sōtēría, kaì éstai hágionʼ kaì kataklēronomḗsousin ho hoíkos Iakṑb toùs kataklēronomḗsantas autoús."],[1,18,"καὶ ἔσται ὁ οἶκος Ἰακὼβ πῦρ, ὁ δὲ οἶκος Ἰωσὴφ φλόξ, ὁ δὲ οἶκος Ἠσαύ εἰς καλάμην, καὶ ἐκκαυθήσονται εἰς αὐτοὺς καὶ καταφάγονται αὐτούς, καὶ οὐκ ἔσται πυροφόρος τῷ οἴκῳ Ἠσαύ, διότι Κύριος ἐλάλησεν.","kaì éstai ho oîkos Iakṑb pŷr, ho dè oîkos Iōsḕph phlóx, ho dè oîkos Ēsaú eis kalámēn, kaì ekkauthḗsontai eis autoùs kaì kataphágontai autoús, kaì ouk éstai pyrophóros tō̂i oíkōi Ēsaú, dióti Kýrios elálēsen."],[1,19,"καὶ κατακληρονομήσουσιν οἱ ἐν Νάγεβ τὸ ὄρος τὸ Ἠσαύ, καὶ οἱ ἐν τῇ Σεφηλὰ τοὺς ἀλλοφύλους· καὶ κατακληρονομήσουσιν τὸ ὄρος Ἐφράιμ καὶ τὸ πεδίον Σαμαρείας καὶ Βενιαμεὶν καὶ τὴν Γαλααδεῖτιν.","kaì kataklēronomḗsousin hoi en Nágeb tò óros tò Ēsaú, kaì hoi en tē̂i Sephēlà toùs allophýlous: kaì kataklēronomḗsousin tò óros Ephráim kaì tò pedíon Samareías kaì Beniameìn kaì tḕn Galaadeîtin."],[1,20,"καὶ τῆς μετοικεσίας ἡ ἀρχὴ αὕτη· τοῖς υἱοῖς Ἰσραήλ, γῆ τῶν Χαναναίων ἕως Σαρέπτων, καὶ ἡ μετοικεσία Ἰερουσαλὴμ ἕως Ἐφράθα· κληρονομήσουσιν τὰς πόλεις τοῦ Νάγεβ.","kaì tē̂s metoikesías hē archḕ haútē: toîs hyioîs Israḗl, gē̂ tō̂n Chananaíōn héōs Saréptōn, kaì hē metoikesía Ierousalḕm héōs Ephrátha: klēronomḗsousin tàs póleis toû Nágeb."],[1,21,"καὶ ἀναβήσονται ἀνασωζόμενοι ἐξ ὄρους Σειὼν τοῦ ἐκδικῆσαι τὸ ὄρος Ἠσαύ, καὶ ἔσται τῷ κυρίῳ ἡ βασιλεία.","kaì anabḗsontai anasōzómenoi ex órous Seiṑn toû ekdikē̂sai tò óros Ēsaú, kaì éstai tō̂i kyríōi hē basileía."]],"chu-elizabeth":[[1,1,"Видение Авдиино: сия глаголет Господь Бог Идумеи: слух слышах от Господа, известие во языки посла: востаните, и востанем на ню ратию.","Videnie Avdiino: siâ glagolet Gospodʹ Bog Idumei: sluh slyšah ot Gospoda, izvestie vo âzyki posla: vostanite, i vostanem na nû ratiû."],[1,2,"Се, мала дах тя во языцех, безчестен ты еси зело.","Se, mala dah tâ vo âzyceh, bezčesten ty esi zelo."],[1,3,"Презорство сердца твоего воздвиже тя живущаго в пещерах каменных: возвышаяй храмину свою, глаголяй в сердцы своем: кто мя свержет на землю?","Prezorstvo serdca tvoego vozdviže tâ živuŝago v peŝerah kamennyh: vozvyšaâj hraminu svoû, glagolâj v serdcy svoem: kto mâ sveržet na zemlû?"],[1,4,"Аще вознесешися якоже орел и аще положиши гнездо твое среде звезд, и оттуду свергу тя, глаголет Господь.","Aŝe voznesešisâ âkože orel i aŝe položiši gnezdo tvoe srede zvezd, i ottudu svergu tâ, glagolet Gospodʹ."],[1,5,"Аще бы татие влезли к тебе, или разбойницы нощию, камо бы повержен был еси? Еда не украли бы доволных себе? Или аще бы объемлющии виноград влезли к тебе, еда бы не оставили гроздия?","Aŝe by tatie vlezli k tebe, ili razbojnicy noŝiû, kamo by poveržen byl esi? Eda ne ukrali by dovolnyh sebe? Ili aŝe by obʺemlûŝii vinograd vlezli k tebe, eda by ne ostavili grozdiâ?"],[1,6,"Како обыскася Исав, и взята быша сокровенная его?","Kako obyskasâ Isav, i vzâta byša sokrovennaâ ego?"],[1,7,"Даже до предел испустиша тя: вси мужие завета твоего сопротивишася ти, премогоша тя мужие мирницы твои: (ядущии с тобою) положиша лесть под тобою, несть смысла в них.","Daže do predel ispustiša tâ: vsi mužie zaveta tvoego soprotivišasâ ti, premogoša tâ mužie mirnicy tvoi: (âduŝii s toboû) položiša lestʹ pod toboû, nestʹ smysla v nih."],[1,8,"В той день, глаголет Господь, погублю премудрыя от Идумеи и смысл от горы Исавовы:","V toj denʹ, glagolet Gospodʹ, pogublû premudryâ ot Idumei i smysl ot gory Isavovy:"],[1,9,"и убоятся воини твои, иже от Феман, да отимется человек от горы Исавовы.","i uboâtsâ voini tvoi, iže ot Feman, da otimetsâ čelovek ot gory Isavovy."],[1,10,"Посечения ради и нечестия, еже на брата твоего Иакова, покрыет тя студ, и отвержен будеши во век.","Posečeniâ radi i nečestiâ, eže na brata tvoego Iakova, pokryet tâ stud, i otveržen budeši vo vek."],[1,11,"От негоже дне сопротивился еси во дни пленяющих иноплеменников силу его, и чуждии внидоша во врата его и о Иерусалиме вергоша жребия, и ты был еси яко един от них.","Ot negože dne soprotivilsâ esi vo dni plenâûŝih inoplemennikov silu ego, i čuždii vnidoša vo vrata ego i o Ierusalime vergoša žrebiâ, i ty byl esi âko edin ot nih."],[1,12,"И да не презриши дне брата твоего в день чуждих, и да не порадуешися о сынех Иудиных в день погибели их, и да не велеречиши в день скорби:","I da ne prezriši dne brata tvoego v denʹ čuždih, i da ne poraduešisâ o syneh Iudinyh v denʹ pogibeli ih, i da ne velerečiši v denʹ skorbi:"],[1,13,"и не входи во врата людий Моих в день болезни их, и не презри и ты сонма их в день потребления их, и не совещайся на силу их в день погибели их:","i ne vhodi vo vrata lûdij Moih v denʹ bolezni ih, i ne prezri i ty sonma ih v denʹ potrebleniâ ih, i ne soveŝajsâ na silu ih v denʹ pogibeli ih:"],[1,14,"ниже настой на исходы их потребити избегающыя их, ниже заключай бежащыя их в день скорби.","niže nastoj na ishody ih potrebiti izbegaûŝyâ ih, niže zaklûčaj bežaŝyâ ih v denʹ skorbi."],[1,15,"Понеже близ день Господень на вся языки: якоже сотворил еси, сице будет ти, воздаяние твое воздастся на главу твою.","Poneže bliz denʹ Gospodenʹ na vsâ âzyki: âkože sotvoril esi, sice budet ti, vozdaânie tvoe vozdastsâ na glavu tvoû."],[1,16,"Понеже якоже еси пил на горе Моей святей, испиют вси языцы вино, испиют и снидут, и будут яко не бывшии.","Poneže âkože esi pil na gore Moej svâtej, ispiût vsi âzycy vino, ispiût i snidut, i budut âko ne byvšii."],[1,17,"В горе же Сиони будет спасение, и будет свята: и наследят дом Иаковль наследивших я.","V gore že Sioni budet spasenie, i budet svâta: i nasledât dom Iakovlʹ nasledivših â."],[1,18,"И будет дом Иаковль огнь, дом же Иосифов пламень, а дом Исавов в тростие, и возгорятся на них и поядят я, и не будет избегаяй дому Исавову, яко Господь глагола.","I budet dom Iakovlʹ ognʹ, dom že Iosifov plamenʹ, a dom Isavov v trostie, i vozgorâtsâ na nih i poâdât â, i ne budet izbegaâj domu Isavovu, âko Gospodʹ glagola."],[1,19,"И наследят иже во нагеве гору Исавову, и иже в раздолии иноплеменники: и возмут гору Ефремову и поле Самарийско, и Вениамина и Галаадитиду.","I nasledât iže vo nageve goru Isavovu, i iže v razdolii inoplemenniki: i vozmut goru Efremovu i pole Samarijsko, i Veniamina i Galaaditidu."],[1,20,"И преселения начало сие сыном Израилевым, земля Хананейска до Сарепты: преселение же Иерусалимле до Ефрафа: и наследят грады Нагевовы.","I preseleniâ načalo sie synom Izrailevym, zemlâ Hananejska do Sarepty: preselenie že Ierusalimle do Efrafa: i nasledât grady Nagevovy."],[1,21,"И взыдут спасаемии от горы Сиони, еже отмстити гору Исавлю, и будет царство Господеви.","I vzydut spasaemii ot gory Sioni, eže otmstiti goru Isavlû, i budet carstvo Gospodevi."]]}};